def _tg_fn(name):
    if tgproxy is None:
        return None
    return getattr(tgproxy, name, None)


async def _tg_call(name, *args, **kwargs):
    fn = _tg_fn(name)
    if fn is None:
        return None
    result = fn(*args, **kwargs)
    if inspect.isawaitable(result):
        return await result
    return result


def _b64u_encode(data):
    return base64.urlsafe_b64encode(bytes(data)).rstrip(b"=").decode("ascii")


def _web_base_secret_valid(value):
    text = str(value or "").strip().lower()
    if text.startswith("dd"):
        text = text[2:]
    return len(text) == 32 and all(c in "0123456789abcdef" for c in text)


def _web_base_secret_normalize(value):
    text = str(value or "").strip().lower()
    if text.startswith("dd"):
        text = text[2:]
    return text


def _web_base_secret_bytes():
    if _WEB_BASE_SECRET_HEX and _web_base_secret_valid(_WEB_BASE_SECRET_HEX):
        return bytes.fromhex(_WEB_BASE_SECRET_HEX)
    raw = os.environ.get("TG_WEB_SECRET", "").strip()
    if raw and _web_base_secret_valid(raw):
        return bytes.fromhex(_web_base_secret_normalize(raw))
    return hashlib.sha256(b"proxygosha-secret-from-panel-v1\n" + str(CONFIG["secret_key"]).encode("utf-8")).digest()[:16]


async def _ensure_web_base_secret():
    global _WEB_BASE_SECRET_HEX, _WEB_BASE_SECRET_SOURCE
    if _WEB_BASE_SECRET_HEX and _web_base_secret_valid(_WEB_BASE_SECRET_HEX):
        return _WEB_BASE_SECRET_HEX
    raw_env = os.environ.get("TG_WEB_SECRET", "").strip()
    if raw_env and _web_base_secret_valid(raw_env):
        _WEB_BASE_SECRET_HEX = _web_base_secret_normalize(raw_env)
        _WEB_BASE_SECRET_SOURCE = "env"
        os.environ["TG_WEB_SECRET"] = _WEB_BASE_SECRET_HEX
        return _WEB_BASE_SECRET_HEX
    if raw_env:
        logger.warning("TG_WEB_SECRET in the environment is not a valid 32-hex secret, ignoring it and using a stored or generated secret instead")
    try:
        stored = await db_fetchone(
            "SELECT value FROM settings WHERE key = 'tg_web_secret'",
            "SELECT value FROM settings WHERE key = 'tg_web_secret'"
        )
        if stored and stored["value"] and _web_base_secret_valid(stored["value"]):
            _WEB_BASE_SECRET_HEX = _web_base_secret_normalize(stored["value"])
            _WEB_BASE_SECRET_SOURCE = "stored"
            os.environ["TG_WEB_SECRET"] = _WEB_BASE_SECRET_HEX
            return _WEB_BASE_SECRET_HEX
        generated = secrets.token_hex(16)
        await db_execute(
            "INSERT OR REPLACE INTO settings (key, value) VALUES ('tg_web_secret', ?)",
            "INSERT INTO settings (key, value) VALUES ('tg_web_secret', $1) ON CONFLICT (key) DO UPDATE SET value = $1",
            (generated,),
        )
        _WEB_BASE_SECRET_HEX = generated
        _WEB_BASE_SECRET_SOURCE = "generated"
        os.environ["TG_WEB_SECRET"] = generated
        logger.warning("TG_WEB_SECRET was missing or invalid, a valid secret was generated and stored in the database so WEB proxy links keep working across restarts")
        return _WEB_BASE_SECRET_HEX
    except Exception as exc:
        logger.error("could not read or store the WEB base secret, using a derived fallback for this boot: " + str(exc))
        derived = hashlib.sha256(b"proxygosha-secret-from-panel-v1\n" + str(CONFIG["secret_key"]).encode("utf-8")).digest()[:16].hex()
        _WEB_BASE_SECRET_HEX = derived
        _WEB_BASE_SECRET_SOURCE = "derived"
        os.environ["TG_WEB_SECRET"] = derived
        return _WEB_BASE_SECRET_HEX


def _web_legacy_token_secret_bytes(token):
    base = _web_base_secret_bytes()
    material = hashlib.sha256(b"proxygosha-web-token-secret-v1\n" + base + b"\n" + str(token).strip().lower().encode("ascii")).digest()
    return material[:16]


def _webproxy_validate_secret(value):
    text = str(value or "").strip().lower()
    if text.startswith("dd"):
        text = text[2:]
    if len(text) != 32 or any(c not in "0123456789abcdef" for c in text):
        raise HTTPException(status_code=400, detail="WEB proxy secret must be 32 hex characters, optionally prefixed with dd")
    return text


def _webproxy_new_secret_hex():
    return secrets.token_hex(16)


def _web_secret_bytes_for_link(link):
    link = link or {}
    stored = str(link.get("webproxy_secret_enc") or "").strip()
    if stored:
        plain = decrypt_proxy_password(stored)
        if plain:
            clean = str(plain).strip().lower()
            if clean.startswith("dd"):
                clean = clean[2:]
            try:
                parsed = bytes.fromhex(clean)
            except ValueError:
                parsed = b""
            if len(parsed) == 16:
                return parsed
    raise ValueError("WEB inbound has no stored secret")


async def _web_migrate_legacy_secret(link):
    try:
        _web_secret_bytes_for_link(link)
        return
    except ValueError:
        pass
    token = str((link or {}).get("webproxy_token") or "").strip().lower()
    if not token:
        return
    try:
        enc = encrypt_proxy_password(_web_legacy_token_secret_bytes(token).hex())
    except Exception:
        return
    if not enc:
        return
    try:
        await db_execute("UPDATE links SET webproxy_secret_enc = ? WHERE uid = ?", "UPDATE links SET webproxy_secret_enc = $1 WHERE uid = $2", (enc, str(link.get("uid", ""))))
    except Exception:
        return
    link["webproxy_secret_enc"] = enc


def _web_secret_hex_for_link(link):
    return _web_secret_bytes_for_link(link).hex()


def _web_secret_hex_or_empty(link):
    try:
        return _web_secret_hex_for_link(link)
    except ValueError:
        return ""


def _web_link_use_port(link=None, port=None):
    use_port = 443
    if port is not None:
        try:
            use_port = int(port)
        except (TypeError, ValueError):
            use_port = 443
    elif link is not None:
        try:
            use_port = int(link.get("port") or 443)
        except (TypeError, ValueError):
            use_port = 443
    if not use_port:
        use_port = 443
    return use_port


def _web_link_secret_for_link(link, port=None):
    if _web_link_use_port(link, port) == 443:
        return "dd" + _web_secret_bytes_for_link(link).hex()
    return _b64u_encode(b"\x70\xdd" + _web_secret_bytes_for_link(link))


def _web_link_server(host, token, link=None, port=None):
    token = str(token or "").strip().lower()
    use_port = _web_link_use_port(link, port)
    server = str(host)
    if use_port != 443:
        server += ":" + str(use_port)
    if use_port == 443:
        return server
    return server + "/" + token


def _web_link(host, token, link=None, port=None):
    token = str(token or "").strip().lower()
    if not token:
        return ""
    if link is None:
        return ""
    try:
        secret = _web_link_secret_for_link(link, port)
    except ValueError:
        return ""
    return "tg://webproxy?server=" + _web_link_server(host, token, link, port) + "&secret=" + secret


def _web_link_https(host, token, link=None, port=None):
    token = str(token or "").strip().lower()
    if not token:
        return ""
    if link is None:
        return ""
    try:
        secret = _web_link_secret_for_link(link, port)
    except ValueError:
        return ""
    return "https://t.me/webproxy?server=" + _web_link_server(host, token, link, port) + "&secret=" + secret


def _web_capability_for_client_secret(host, base_path, client_secret):
    host = str(host).strip().lower()
    base_path = str(base_path or "").strip().lower()
    if base_path:
        context = "tdesktop-web-proxy-bridge-v2\n" + host + "\n" + base_path
    else:
        context = "tdesktop-web-proxy-bridge-v1\n" + host
    mac = hmac_mod.new(bytes(client_secret), context.encode("utf-8"), hashlib.sha256).digest()
    return _b64u_encode(mac)


def _web_capability(host, token, link):
    return _web_capability_for_client_secret(host, token, b"\xdd" + _web_secret_bytes_for_link(link))


def _web_capability_v1(host, token, link):
    return _web_capability_for_client_secret(host, "", b"\xdd" + _web_secret_bytes_for_link(link))


def _webproxy_parse_client_link(link_text):
    text = str(link_text or "").strip()
    parsed_url = urlparse(text)
    scheme = str(parsed_url.scheme or "").lower()
    if scheme == "tg":
        if str(parsed_url.netloc or "").lower() != "webproxy":
            raise ValueError("link is not a tg://webproxy link")
    elif scheme == "https":
        if str(parsed_url.netloc or "").lower() != "t.me" or str(parsed_url.path or "").strip("/") != "webproxy":
            raise ValueError("link is not a https://t.me/webproxy link")
    else:
        raise ValueError("link is not a tg://webproxy or https://t.me/webproxy link")
    query = parse_qs(parsed_url.query, keep_blank_values=True)
    servers = query.get("server") or []
    secrets = query.get("secret") or []
    if len(servers) != 1 or len(secrets) != 1 or not servers[0] or not secrets[0]:
        raise ValueError("link must carry exactly one server and one secret parameter")
    server = unquote(str(servers[0]))
    secret_param = str(secrets[0])
    if "/" in server:
        hostport, base_path = server.split("/", 1)
        hostport = str(hostport or "").strip().lower()
        base_path = str(base_path or "").strip()
        if not hostport or not base_path or "/" in base_path:
            raise ValueError("path-form link server must be host/base with a single base segment")
        link_port = 443
        if ":" in hostport:
            host, port_text = hostport.rsplit(":", 1)
            host = str(host or "").strip().lower()
            try:
                link_port = int(port_text)
            except (TypeError, ValueError):
                raise ValueError("path-form link server port is not a number")
            if link_port <= 0 or link_port > 65535:
                raise ValueError("path-form link server port is out of range")
        else:
            host = hostport
        try:
            raw = base64.urlsafe_b64decode(secret_param + "=" * (-len(secret_param) % 4))
        except Exception:
            raise ValueError("path-form link secret is not valid unpadded base64url")
        if len(raw) < 17 or raw[0] != 0x70:
            raise ValueError("path-form link secret must be unpadded base64url of 0x70 followed by the client secret")
        client_secret = raw[1:]
        if len(client_secret) == 17 and client_secret[0] == 0xDD:
            secret_bytes = bytes(client_secret[1:])
        elif len(client_secret) == 16:
            secret_bytes = bytes(client_secret)
        else:
            raise ValueError("path-form link client secret must be 16 bytes, optionally prefixed with 0xdd")
        return {"host": host, "port": link_port, "base_path": base_path, "form": "path", "client_secret": bytes(client_secret), "secret_bytes": secret_bytes}
    host = str(server or "").strip().lower()
    if not host or ":" in host:
        raise ValueError("root-form link server must be a bare host with no port and no path")
    lowered = secret_param.lower()
    if len(lowered) == 34 and lowered.startswith("dd") and all(c in "0123456789abcdef" for c in lowered[2:]):
        secret_bytes = bytes.fromhex(lowered[2:])
        return {"host": host, "port": 443, "base_path": "", "form": "root", "client_secret": b"\xdd" + secret_bytes, "secret_bytes": secret_bytes}
    if len(lowered) == 32 and all(c in "0123456789abcdef" for c in lowered):
        secret_bytes = bytes.fromhex(lowered)
        return {"host": host, "port": 443, "base_path": "", "form": "root", "client_secret": secret_bytes, "secret_bytes": secret_bytes}
    raise ValueError("root-form link secret must be 32 hex characters, optionally prefixed with dd")


def _webproxy_capability_for_parsed(parsed):
    return _web_capability_for_client_secret(parsed["host"], parsed["base_path"], parsed["client_secret"])


def _webproxy_assert_emitted_link(link_text, host, port, token):
    parsed = _webproxy_parse_client_link(link_text)
    expected_host = str(host or "").strip().lower()
    if parsed["host"] != expected_host:
        raise ValueError("emitted link server host is " + parsed["host"] + " instead of " + expected_host)
    use_port = int(port or 443)
    if use_port == 443:
        if parsed["form"] != "root" or parsed["base_path"] != "":
            raise ValueError("a port 443 link must be the bare-domain root form with a dd-prefixed hex secret")
        if len(parsed["client_secret"]) != 17 or parsed["client_secret"][0] != 0xDD:
            raise ValueError("a port 443 root link must carry the dd-mode hex secret")
    else:
        if parsed["form"] != "path":
            raise ValueError("a non-443 link must be the token-path form with a marked base64url secret")
        if int(parsed.get("port") or 443) != use_port:
            raise ValueError("token-path link server port does not match this inbound port")
        if parsed["base_path"] != str(token or "").strip().lower():
            raise ValueError("token-path link base does not match this inbound token")
        if len(parsed["client_secret"]) != 17 or parsed["client_secret"][0] != 0xDD:
            raise ValueError("a token-path link must carry the dd-mode marked secret")
    return parsed


def _web_rewrite_bridge_query(query, capability):
    params = parse_qs(query.decode("latin-1"), keep_blank_values=True)
    replaced = False
    for key in ("bridge", "capability", "cap"):
        if key in params:
            params[key] = [capability]
            replaced = True
    if not replaced:
        return query
    return urlencode(params, doseq=True).encode("latin-1")


def _web_verify_token_bridge(request, token, link):
    capability = request.query_params.get("bridge", "") or request.query_params.get("capability", "") or request.query_params.get("cap", "") or request.headers.get("x-tgweb-capability", "")
    if not capability:
        return None
    host = get_domain(request)
    try:
        expected_v2 = _web_capability(host, token, link)
    except ValueError:
        return False
    if not hmac_mod.compare_digest(capability, expected_v2):
        return False
    return _web_capability_v1(host, token, link)


def _gen_proxy_code(n=12):
    taken = {str(l.get("proxy_username") or "").strip() for l in LINKS.values() if str(l.get("proxy_username") or "").strip()}
    for _attempt in range(64):
        code = "".join(secrets.choice(_PROXY_CODE_ALPHABET) for _ in range(int(n)))
        if code not in taken:
            return code
    raise RuntimeError("could not allocate a unique proxy credential code")


def _validate_proxy_creds(user, pw):
    user = str(user or "").strip()
    pw = str(pw or "").strip()
    if not user and not pw:
        return
    if not user or not pw:
        raise HTTPException(status_code=400, detail="Proxy username and password must both be set")
    if len(user) < 1 or len(user) > 64 or len(pw) < 1 or len(pw) > 64:
        raise HTTPException(status_code=400, detail="Proxy username and password must each be 1 to 64 characters")
    forbidden_user = set(":@/?#")
    for ch in user:
        if ch in forbidden_user or ch.isspace() or ord(ch) < 32 or ord(ch) == 127:
            raise HTTPException(status_code=400, detail="Proxy username must not contain : @ / ? # whitespace or control characters")
    for ch in pw:
        if ch.isspace() or ord(ch) < 32 or ord(ch) == 127:
            raise HTTPException(status_code=400, detail="Proxy password must not contain whitespace or control characters")


def _proxy_creds_for_link(link):
    user = str((link or {}).get("proxy_username") or "").strip()
    pw = str((link or {}).get("proxy_password") or "").strip()
    if user and pw:
        return user, pw
    uid = str((link or {}).get("uid") or "")
    return uid, uid


def _link_by_proxy_username(username):
    username = str(username or "").strip()
    if not username:
        return None
    link = LINKS.get(username)
    if link is not None:
        return link
    for candidate in LINKS.values():
        if str(candidate.get("proxy_username") or "").strip() == username:
            return candidate
    return None


def _link_for_proxy_session(username):
    return _link_by_proxy_username(username)


def _live_proxy_unflushed_bytes(uid):
    if tgproxy is None:
        return 0
    try:
        sessions = tgproxy.active_proxy_sessions()
    except Exception:
        return 0
    total = 0
    for s in sessions or []:
        link = _link_for_proxy_session(s.get("username") or "")
        if link is None or str(link.get("uid") or "") != str(uid):
            continue
        total += max(0, int(s.get("bytes_up", 0) or 0) + int(s.get("bytes_down", 0) or 0) - int(s.get("bytes_flushed", 0) or 0))
    if str(uid) not in _TELEMT_WEB_STATS:
        try:
            username_fn = _tg_fn("telemt_web_username")
            username = str(username_fn(uid)) if username_fn is not None else ""
            status = _telemt_web_status_cached(_TELEMT_ROOT_CHILD_UID)
            rows = _telemt_web_sessions_value(status)
            if username and isinstance(rows, list):
                for row in rows:
                    if isinstance(row, dict) and str(row.get("user") or "") == username:
                        total += max(0, int(row.get("bytes_up", 0) or 0) + int(row.get("bytes_down", 0) or 0) - int(row.get("bytes_flushed", 0) or 0))
        except Exception:
            pass
    return total


def _oldest_active_web():
    rows = [l for l in LINKS.values() if (l.get("protocol") or "") == "webproxy" and l.get("active")]
    if not rows:
        return None
    rows.sort(key=lambda l: str(l.get("created_at") or ""))
    return rows[0]


def _telemt_web_port_for_uid(uid):
    fn = _tg_fn("telemt_web_port")
    if fn is None:
        return None
    try:
        port = fn(uid)
    except Exception:
        return None
    if inspect.isawaitable(port):
        try:
            port.close()
        except Exception:
            pass
        return None
    try:
        port = int(port)
    except (TypeError, ValueError):
        return None
    return port if port > 0 else None


def _telemt_web_status_cached(uid):
    entry = _TELEMT_WEB_STATUS_CACHE.get(uid)
    if not entry:
        return {}
    return entry[0] if isinstance(entry, tuple) else {}


def _telemt_web_sessions_value(status):
    rows = (status or {}).get("session_rows")
    if isinstance(rows, list):
        return rows
    sessions = (status or {}).get("sessions")
    if isinstance(sessions, list):
        return sessions
    if isinstance(sessions, int):
        return sessions
    return 0


async def _telemt_refresh_web_status():
    try:
        status = await _tg_call("telemt_web_status", _TELEMT_ROOT_CHILD_UID)
    except Exception:
        status = None
    if isinstance(status, dict):
        _TELEMT_WEB_STATUS_CACHE[_TELEMT_ROOT_CHILD_UID] = (status, time.monotonic())


def _web_sessions_for_uid(uid):
    status = _telemt_web_status_cached(_TELEMT_ROOT_CHILD_UID)
    rows = _telemt_web_sessions_value(status)
    if isinstance(rows, int):
        active = [l for l in LINKS.values() if (l.get("protocol") or "") == "webproxy" and l.get("active")]
        return rows if len(active) == 1 else 0
    if not isinstance(rows, list):
        return []
    username_fn = _tg_fn("telemt_web_username")
    username = str(username_fn(uid)) if username_fn is not None else ""
    if not username:
        return []
    return [row for row in rows if isinstance(row, dict) and str(row.get("user") or "") == username]


async def _telemt_root_child_is_rooted():
    try:
        checked = await _tg_call("telemt_web_base_path", _TELEMT_ROOT_CHILD_UID)
    except Exception:
        return False
    if not isinstance(checked, tuple) or len(checked) != 2:
        return False
    base_path, err = checked
    if err:
        return False
    return base_path == ""


async def _telemt_sync_root_vhost():
    global _TELEMT_ROOT_PROFILE_KEY
    async with _TELEMT_ROOT_SYNC_LOCK:
        rows = [l for l in LINKS.values() if (l.get("protocol") or "") == "webproxy" and l.get("active")]
        rows.sort(key=lambda l: str(l.get("created_at") or ""))
        host = get_domain()
        profiles = []
        for link in rows:
            try:
                secret_hex = _web_secret_hex_for_link(link)
            except ValueError as exc:
                WEBPROXY_STATE["child_errors"][_TELEMT_ROOT_CHILD_UID] = str(exc)
                return
            max_sessions = int(link.get("max_connections") or 0)
            if max_sessions <= 0:
                max_sessions = 8
            profiles.append({"uid": str(link.get("uid", "")), "secret_hex": secret_hex, "max_sessions": max_sessions, "max_streams": 512})
        key = host + "|" + "|".join(sorted(item["uid"] + ":" + item["secret_hex"] + ":" + str(item["max_sessions"]) for item in profiles))
        if not profiles:
            if _TELEMT_ROOT_PROFILE_KEY:
                try:
                    await _tg_call("telemt_stop_web", _TELEMT_ROOT_CHILD_UID)
                except Exception:
                    pass
                _TELEMT_PROVISIONED["web"].discard(_TELEMT_ROOT_CHILD_UID)
                _TELEMT_ROOT_PROFILE_KEY = ""
                _TELEMT_ROOT_SYNC_STATE["last_key"] = ""
                _TELEMT_ROOT_SYNC_STATE["last_error"] = ""
                WEBPROXY_STATE["child_errors"].pop(_TELEMT_ROOT_CHILD_UID, None)
            return
        if key == _TELEMT_ROOT_PROFILE_KEY and _TELEMT_ROOT_CHILD_UID in _TELEMT_PROVISIONED.get("web", set()):
            if await _telemt_root_child_is_rooted():
                WEBPROXY_STATE["child_errors"].pop(_TELEMT_ROOT_CHILD_UID, None)
                return
            if _TELEMT_ROOT_SYNC_STATE.get("last_key") == key and time.monotonic() - float(_TELEMT_ROOT_SYNC_STATE.get("last_attempt") or 0) < _TELEMT_ROOT_SYNC_COOLDOWN_SECONDS:
                return
        public_ip = None
        try:
            resolved = await resolve_domain_to_ip(host)
            if resolved:
                public_ip = resolved
        except Exception:
            public_ip = None
        _TELEMT_ROOT_SYNC_STATE["last_attempt"] = time.monotonic()
        _TELEMT_ROOT_SYNC_STATE["last_key"] = key
        if _telemt_web_port_for_uid(_TELEMT_ROOT_CHILD_UID) is not None and _tg_fn("telemt_web_sync_profiles") is not None:
            try:
                synced = await _tg_call("telemt_web_sync_profiles", _TELEMT_ROOT_CHILD_UID, profiles, host)
            except Exception:
                synced = False
            if synced:
                if await _telemt_root_child_is_rooted():
                    _TELEMT_PROVISIONED["web"].add(_TELEMT_ROOT_CHILD_UID)
                    _TELEMT_ROOT_PROFILE_KEY = key
                    _TELEMT_ROOT_SYNC_STATE["last_error"] = ""
                    WEBPROXY_STATE["child_errors"].pop(_TELEMT_ROOT_CHILD_UID, None)
                    return
                start_err = "telemt shared WEB child synced but its vhost is not at the root"
            else:
                start_err = "telemt shared WEB child profile sync failed, restarting it with the full profile set"
        else:
            start_err = ""
        first_secret = profiles[0]["secret_hex"]
        first_sessions = profiles[0]["max_sessions"]
        result = None
        try:
            result = await _tg_call("telemt_start_web", _TELEMT_ROOT_CHILD_UID, _TELEMT_ROOT_CHILD_TOKEN, first_secret, host, max_sessions=first_sessions, max_streams=512, public_ip=public_ip, root_enabled=True, profiles=profiles)
        except TypeError:
            result = {"enabled": False, "error": "telemt WEB start does not support shared profiles"}
        except Exception as _exc:
            result = {"enabled": False, "error": "telemt WEB start failed: " + str(_exc)}
        if isinstance(result, dict) and result.get("enabled"):
            if await _telemt_root_child_is_rooted():
                _TELEMT_PROVISIONED["web"].add(_TELEMT_ROOT_CHILD_UID)
                _TELEMT_ROOT_PROFILE_KEY = key
                _TELEMT_ROOT_SYNC_STATE["last_error"] = ""
                WEBPROXY_STATE["child_errors"].pop(_TELEMT_ROOT_CHILD_UID, None)
                return
            start_err = "telemt shared WEB child started but its vhost is not at the root"
        elif isinstance(result, dict):
            start_err = str(result.get("error") or "telemt shared WEB child did not start")
        elif _tg_fn("telemt_start_web") is None:
            start_err = "telemt WEB start is not available in the telegram module"
        else:
            start_err = "telemt shared WEB child did not start"
        detail = ""
        try:
            detail_fn = _tg_fn("telemt_web_root_error")
            if detail_fn is not None:
                detail = str(detail_fn(_TELEMT_ROOT_CHILD_UID) or "")
        except Exception:
            detail = ""
        err = start_err
        if detail:
            err = err + "; shared vhost error: " + detail
        WEBPROXY_STATE["child_errors"][_TELEMT_ROOT_CHILD_UID] = err
        _TELEMT_ROOT_SYNC_STATE["last_error"] = err
        logger.error("telemt shared WEB child failed: " + err)


def _telemt_valid_tls_host(host):
    if not isinstance(host, str):
        return False
    text = host.strip().lower()
    if not text or text.startswith((".", "-")) or text.endswith((".", "-")) or ".." in text:
        return False
    for ch in text:
        if ch.isspace() or ch in ("/", "\\"):
            return False
    try:
        parsed = urlparse("https://" + text + "/")
    except ValueError:
        return False
    return bool(parsed.hostname)


def _telemt_mtproto_default_domain(request=None):
    return "www.google.com"


def _mtproto_mask_domain_warning(domain, request=None):
    text = str(domain or "").strip().lower()
    if not text:
        return ""
    host = get_domain(request)
    if not isinstance(host, str):
        return ""
    host = host.strip().lower()
    if not host or host == "localhost":
        return ""
    if text != host:
        return ""
    return "Fake-TLS mask domain is the panel's own domain (" + text + "); the mask must be a third-party domain or the FakeTLS handshake loops back to the panel itself. Use www.google.com or another third-party domain. " + "دامنه mask برای Fake-TLS همان دامنه خود پنل است؛ mask باید یک دامنه شخص ثالث باشد وگرنه handshake به خود پنل برمی‌گردد. از www.google.com یا یک دامنه شخص ثالث دیگر استفاده کنید."


def _telemt_mtproto_tls_wanted(rows=None):
    primary = _telemt_mtproto_default_domain()
    extras = {"www.google.com"}
    if rows is None:
        rows = list(LINKS.values())
    for link in rows:
        if (link.get("protocol") or "") != "mtproto" or not link.get("active"):
            continue
        dom = str(link.get("mtproto_domain") or "").strip().lower()
        if _telemt_valid_tls_host(dom):
            extras.add(dom)
    extras.discard(primary)
    return primary, sorted(extras)


def _telemt_mtproto_links_wanted(rows=None):
    host = get_domain(None)
    if not isinstance(host, str):
        host = ""
    host = host.strip().lower()
    if not host or host == "localhost":
        return None, None
    if rows is None:
        rows = list(LINKS.values())
    oldest_port = None
    oldest_at = None
    for link in rows:
        if (link.get("protocol") or "") != "mtproto" or not link.get("active"):
            continue
        try:
            port = int(link.get("port") or 0)
        except (TypeError, ValueError):
            port = 0
        if not port:
            continue
        created = str(link.get("created_at") or "")
        if oldest_port is None or created < oldest_at:
            oldest_port = port
            oldest_at = created
    if oldest_port is None:
        return None, None
    return host, oldest_port


async def _telemt_provision_mtproto(link):
    uid = str(link.get("uid", ""))
    secret_fn = _tg_fn("mtproxy_secret_for_uid")
    if secret_fn is None:
        raise ValueError("MTProto secret derivation is not available in the telegram module")
    secret = secret_fn(uid)
    if isinstance(secret, (bytes, bytearray)):
        secret_hex = bytes(secret).hex()
    else:
        secret_hex = str(secret).strip()
    variant = str(link.get("mtproto_variant") or "dd").strip().lower() or "dd"
    domain = str(link.get("mtproto_domain") or "www.google.com").strip() or "www.google.com"
    max_conns = int(link.get("max_connections") or 0)
    limit_bytes = int(link.get("limit_bytes") or 0)
    expires_at = link.get("expires_at") or None
    tls_primary, tls_extras = _telemt_mtproto_tls_wanted()
    links_host, links_port = _telemt_mtproto_links_wanted()
    try:
        await _tg_call("mtproxy_register_link", uid)
    except Exception:
        pass
    result = await _tg_call("telemt_mtproto_upsert_user", uid, secret_hex, variant=variant, domain=domain, max_conns=max_conns, limit_bytes=limit_bytes, expires_at=expires_at, tls_domain=tls_primary, tls_domains=tls_extras, public_host=links_host, public_port=links_port)
    if result is False:
        raise ValueError("telemt MTProto user provisioning was rejected")
    if result is None and _tg_fn("telemt_mtproto_upsert_user") is None:
        raise ValueError("telemt MTProto provisioning is not available in the telegram module")
    _TELEMT_PROVISIONED["mtproto"].add(uid)


async def _telemt_remove_mtproto(uid):
    uid = str(uid or "")
    try:
        await _tg_call("mtproxy_unregister_link", uid)
    except Exception:
        pass
    try:
        await _tg_call("telemt_mtproto_remove_user", uid)
    except Exception:
        pass
    _TELEMT_PROVISIONED["mtproto"].discard(uid)


async def _mtproto_verify_live_tls(link):
    if (link.get("protocol") or "") != "mtproto":
        return ""
    if str(link.get("mtproto_variant") or "dd").strip().lower() != "faketls":
        return ""
    domain = str(link.get("mtproto_domain") or "").strip().lower()
    if not domain:
        return ""
    try:
        live = await _tg_call("telemt_mtproto_tls")
    except Exception:
        live = None
    if not isinstance(live, (list, tuple)) or len(live) != 2:
        return "Fake-TLS domain " + domain + " could not be verified against the telemt MTProto child (child TLS state unavailable); the ee link may not work until the child is up."
    live_set = {str(live[0] or "").strip().lower()}
    for item in live[1] or []:
        live_set.add(str(item or "").strip().lower())
    live_set.discard("")
    if domain not in live_set:
        return "Fake-TLS domain " + domain + " is not in the telemt MTProto child TLS set (" + ", ".join(sorted(live_set)) + "); the ee link will be dropped by the child until the domain is applied."
    return ""


async def _telemt_sync_link(link, previous=None):
    if link is None:
        return
    uid = str(link.get("uid", ""))
    protocol = (link.get("protocol") or "")
    prev_protocol = str((previous or {}).get("protocol") or "") if previous else ""
    prev_active = bool((previous or {}).get("active")) if previous else None
    now_active = bool(link.get("active"))
    if prev_protocol and prev_protocol != protocol:
        if prev_protocol == "webproxy":
            await _telemt_sync_root_vhost()
        elif prev_protocol == "mtproto":
            await _telemt_remove_mtproto(uid)
        previous = None
        prev_active = None
    if not now_active:
        if prev_active or previous is None:
            if protocol == "mtproto":
                await _telemt_remove_mtproto(uid)
        if protocol == "webproxy":
            await _telemt_sync_root_vhost()
        return
    relevant = ("webproxy_token", "webproxy_secret_enc", "port", "mtproto_variant", "mtproto_domain", "max_connections", "limit_bytes", "expires_at", "active", "protocol")
    changed = False
    if previous is None:
        changed = True
    else:
        for key in relevant:
            if str((previous or {}).get(key) or "") != str(link.get(key) or ""):
                changed = True
                break
    if protocol == "webproxy":
        await _web_migrate_legacy_secret(link)
        await _telemt_sync_root_vhost()
    elif protocol == "mtproto":
        provisioned = uid in _TELEMT_PROVISIONED["mtproto"]
        if changed or not provisioned:
            try:
                await _telemt_provision_mtproto(link)
            except Exception as exc:
                logger.error("telemt MTProto provisioning failed for " + uid + ": " + str(exc))
