async def create_direct_proxy_connection(host, port, link):
    stored = (link.get("outbound_proxy") or "").strip()
    if not stored:
        raise ConnectionError("Outbound proxy line is empty")
    try:
        proxy_host, proxy_port, proxy_user, _ignored = parse_outbound_proxy_line(stored)
    except ValueError as e:
        raise ConnectionError("Outbound proxy line is invalid: " + str(e))
    proxy_pass = decrypt_proxy_password(link.get("outbound_proxy_pass") or "")
    auth = ""
    if proxy_user:
        auth = quote(proxy_user) + ":" + quote(proxy_pass) + "@"
    shown_host = proxy_host
    if ":" in shown_host and not shown_host.startswith("["):
        shown_host = "[" + shown_host + "]"
    proxy_url = "socks5:" + "/" + "/" + auth + shown_host + ":" + str(proxy_port)
    try:
        proxy = Proxy.from_url(proxy_url)
        sock = await asyncio.wait_for(proxy.connect(dest_host=host, dest_port=port), timeout=10.0)
        reader, writer = await asyncio.open_connection(sock=sock)
        tune_socket_for_link(writer, link)
        return reader, writer
    except asyncio.TimeoutError as e:
        raise ConnectionError("Outbound proxy SOCKS5 timed out") from e
    except Exception as e:
        raise ConnectionError("Outbound proxy SOCKS5 failed: " + str(e)) from e


def _link_session_count(uid):
    return sum(1 for info in connections.values() if info.get("uuid") == uid)


def _user_session_count(user_id):
    if not user_id:
        return 0
    uids = {l["uid"] for l in LINKS.values() if l.get("owner_user_id") == user_id}
    return sum(1 for info in connections.values() if info.get("uuid") in uids)


def _proxy_session_count(uid):
    if tgproxy is None:
        return 0
    total = 0
    try:
        for s in tgproxy.active_proxy_sessions():
            username = s.get("username") or ""
            if username == uid:
                total += 1
                continue
            link = _link_for_proxy_session(username)
            if link is not None and str(link.get("uid") or "") == uid:
                total += 1
    except Exception:
        pass
    try:
        sessions = _web_sessions_for_uid(uid)
        if isinstance(sessions, list):
            total += len(sessions)
        elif isinstance(sessions, int):
            total += sessions
    except Exception:
        pass
    return total


def _normalize_client_ip(ip):
    raw = str(ip or "").strip()
    if raw.lower().startswith("::ffff:"):
        return raw[7:]
    return raw


def _dest_label(row):
    dest = str(row.get("destination") or "").strip()
    if dest:
        return dest
    transport = str(row.get("transport") or row.get("protocol") or "")
    if transport in ("mtproto", "webproxy"):
        return "Telegram DC"
    if transport in ("socks5", "http-proxy"):
        return "General destination"
    return ""


def subnet24_of(ip):
    raw = _normalize_client_ip(ip)
    if not raw:
        return "unknown"
    try:
        addr = ipaddress.ip_address(raw)
    except ValueError:
        return "unknown"
    if isinstance(addr, ipaddress.IPv4Address):
        return str(ipaddress.ip_network(raw + "/24", strict=False))
    return str(ipaddress.ip_network(raw + "/64", strict=False))


def _session_limit_reason(link, uuid, client_ip, exclude_conn_id=None):
    max_conn = int(link.get("max_connections") or 0)
    if max_conn > 0:
        n = sum(1 for cid, info in connections.items() if info.get("uuid") == uuid and cid != exclude_conn_id)
        n += _proxy_session_count(uuid)
        if n >= max_conn:
            return "connection limit"
    if not is_ip_allowed(link, uuid, client_ip):
        return "ip limit"
    owner = (link.get("owner_user_id") or "").strip()
    if owner:
        max_sess = int(USER_MAX_SESSIONS.get(owner, 0) or 0)
        if max_sess > 0:
            uids = {l["uid"] for l in LINKS.values() if l.get("owner_user_id") == owner}
            n = sum(1 for cid, info in connections.items() if info.get("uuid") in uids and cid != exclude_conn_id)
            if tgproxy is not None:
                try:
                    for s in tgproxy.active_proxy_sessions():
                        username = s.get("username") or ""
                        if username in uids:
                            n += 1
                            continue
                        link = _link_for_proxy_session(username)
                        if link is not None and str(link.get("uid") or "") in uids:
                            n += 1
                except Exception:
                    pass
                try:
                    for member_uid in uids:
                        sessions = _web_sessions_for_uid(member_uid)
                        if isinstance(sessions, list):
                            n += len(sessions)
                        elif isinstance(sessions, int):
                            n += sessions
                except Exception:
                    pass
            if n >= max_sess:
                return "user session limit"
    return None


def _xhttp_add_up(sess, n):
    c = connections.get(sess.get("conn_id", ""))
    if c:
        c["bytes"] = c.get("bytes", 0) + n
        c["bytes_up"] = c.get("bytes_up", 0) + n


def parse_outbound_proxy(line):
    raw = (line or "").strip()
    if not raw:
        raise ValueError("empty proxy line")
    if "://" in raw:
        scheme, rest = raw.split("://", 1)
        if scheme.lower() not in ("socks5", "socks"):
            raise ValueError("only socks5:// is supported")
    else:
        rest = raw
    if "@" in rest:
        auth, hostport = rest.rsplit("@", 1)
        if ":" in auth:
            username, password = auth.split(":", 1)
        else:
            username, password = auth, ""
    else:
        username, password = "", ""
        hostport = rest
    if ":" not in hostport:
        raise ValueError("proxy line must be host:port")
    host, port_s = hostport.rsplit(":", 1)
    host = host.strip()
    if not host:
        raise ValueError("proxy host is empty")
    try:
        proxy_port = int(port_s)
    except (TypeError, ValueError):
        raise ValueError("proxy port must be a number")
    if proxy_port < 1 or proxy_port > 65535:
        raise ValueError("proxy port out of range")
    return host, proxy_port, unquote(username), unquote(password)


def resolve_outbound_mode(link):
    mode = (link.get("outbound_mode") or "auto").strip().lower()
    if mode not in OUTBOUND_MODES:
        mode = "auto"
    if mode == "auto":
        return "proxy" if (link.get("proxy_line_id") or (link.get("outbound_proxy") or "").strip()) else "direct"
    return mode


def tune_socket_for_link(writer, link):
    tune_socket(writer)
    if link and link.get("tfo"):
        sock = writer.get_extra_info("socket")
        if sock:
            try:
                sock.setsockopt(socket.IPPROTO_TCP, 23, 5)
            except (OSError, AttributeError):
                pass
