def get_proxy_fernet():
    if Fernet is None:
        raise RuntimeError("Proxy password encryption is unavailable")
    env_key = os.environ.get("PROXY_ENCRYPTION_KEY", "").strip()
    if env_key:
        return Fernet(env_key.encode())
    raw = hashlib.sha256(CONFIG["secret_key"].encode()).digest()
    derived = base64.urlsafe_b64encode(raw)
    return Fernet(derived)


def encrypt_proxy_password(plain):
    if not plain:
        return ""
    return get_proxy_fernet().encrypt(str(plain).encode()).decode()


def decrypt_proxy_password(stored):
    if not stored:
        return ""
    value = str(stored)
    if value.startswith("gAAAAA"):
        try:
            return get_proxy_fernet().decrypt(value.encode()).decode()
        except Exception as e:
            logger.error(f"Failed to decrypt proxy password: {e}")
            return ""
    logger.warning("Legacy plaintext proxy password encountered, run migration")
    return value


async def migrate_proxy_passwords():
    try:
        rows = await db_fetchall("SELECT id, password FROM proxy_lines", "SELECT id, password FROM proxy_lines")
    except Exception as e:
        logger.error(f"Proxy password migration read failed: {e}")
        return
    for row in rows:
        stored = row.get("password") or ""
        if not stored or str(stored).startswith("gAAAAA"):
            continue
        try:
            encrypted = encrypt_proxy_password(str(stored))
        except Exception as e:
            logger.error(f"Proxy password migration failed for id={row.get('id')}: {e}")
            continue
        await db_execute("UPDATE proxy_lines SET password = ? WHERE id = ?", "UPDATE proxy_lines SET password = $1 WHERE id = $2", (encrypted, row["id"]))


def parse_outbound_proxy_line(text):
    value = (text or "").strip()
    if not value:
        return "", 0, "", ""
    low = value.lower()
    scheme = "socks5:" + "/" + "/"
    if low.startswith(scheme):
        value = value[len(scheme):]
    elif ("/" + "/") in value:
        raise ValueError("Only SOCKS5 proxy lines are supported")
    if "@" in value:
        userinfo, hostport = value.rsplit("@", 1)
        if ":" in userinfo:
            user, password = userinfo.split(":", 1)
        else:
            user, password = userinfo, ""
    else:
        user, password, hostport = "", "", value
    user = user.strip()
    hostport = hostport.strip()
    if hostport.startswith("["):
        close = hostport.find("]")
        if close < 0 or len(hostport) <= close + 1 or hostport[close + 1] != ":":
            raise ValueError("Invalid IPv6 proxy address")
        host = hostport[1:close]
        port_text = hostport[close + 2:]
    elif hostport.count(":") == 1:
        host, port_text = hostport.split(":", 1)
    else:
        raise ValueError("Proxy line must be host:port")
    host = host.strip()
    if not host:
        raise ValueError("Proxy host is required")
    try:
        ipaddress.ip_address(host)
    except ValueError:
        if len(host) > 253 or not re.match(r"^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$", host) or ".." in host:
            raise ValueError("Invalid proxy host")
    try:
        port = int(port_text)
    except (TypeError, ValueError):
        raise ValueError("Invalid proxy port")
    if port < 1 or port > 65535:
        raise ValueError("Invalid proxy port")
    if not user:
        password = ""
    return host, port, user, password


def split_outbound_proxy_for_store(text, stored_pass=""):
    value = (text or "").strip()
    if not value:
        return "", ""
    host, port, user, password = parse_outbound_proxy_line(value)
    shown = host
    if ":" in shown and not shown.startswith("["):
        shown = "[" + shown + "]"
    line = shown + ":" + str(port)
    if user:
        line = user + "@" + line
    if password:
        stored = encrypt_proxy_password(password)
    elif user and stored_pass:
        stored = stored_pass
    else:
        stored = ""
    return line, stored
