def is_domain_blocked(host: str) -> bool:
    if not host or not BLOCKED_DOMAINS:
        return False
    host_lower = host.lower()
    for blocked in BLOCKED_DOMAINS:
        if blocked.startswith("*."):
            if host_lower.endswith(blocked[1:]) or host_lower == blocked[2:]:
                return True
        elif host_lower == blocked:
            return True
    return False


class QuotaGate:
    def __init__(self, uid: str):
        self.uid = uid
        self.pending = 0
        self.ok = True
        self.last_check = time.monotonic()
        self.batch = 64 * 1024
        self.rate_ewma = 0.0
        self._lock = asyncio.Lock()

    async def add(self, n: int) -> bool:
        async with self._lock:
            if not self.ok:
                return False
            self.pending += n
            now = time.monotonic()
            if self.pending >= self.batch or (now - self.last_check) > 0.2:
                flush, self.pending = self.pending, 0
                self.ok = await consume_quota(self.uid, flush)
                if self.ok:
                    local_now = datetime.now(UTC) + timedelta(hours=TIMEZONE_OFFSET)
                    hour = local_now.strftime("%Y-%m-%d %H:00")
                    day = local_now.strftime("%Y-%m-%d")
                    await add_traffic_to_buffer(hour, day, flush, self.uid)
                    elapsed = now - self.last_check
                    if elapsed > 0:
                        inst_rate = flush / elapsed
                        self.rate_ewma = inst_rate if self.rate_ewma == 0 else (0.7 * self.rate_ewma + 0.3 * inst_rate)
                        target = int(self.rate_ewma * 0.2)
                        self.batch = max(32 * 1024, min(1024 * 1024, target or 64 * 1024))
                self.last_check = now
                return self.ok
            return True

    async def check(self) -> bool:
        async with self._lock:
            if self.pending:
                flush, self.pending = self.pending, 0
                ok = await consume_quota(self.uid, flush)
                if ok:
                    local_now = datetime.now(UTC) + timedelta(hours=TIMEZONE_OFFSET)
                    hour = local_now.strftime("%Y-%m-%d %H:00")
                    day = local_now.strftime("%Y-%m-%d")
                    await add_traffic_to_buffer(hour, day, flush, self.uid)
                    self.ok = True
                    return True
                else:
                    self.ok = False
                    return False
            return self.ok

    async def flush(self) -> bool:
        async with self._lock:
            if self.pending:
                flush, self.pending = self.pending, 0
                self.ok = self.ok and await consume_quota(self.uid, flush)
                if self.ok:
                    local_now = datetime.now(UTC) + timedelta(hours=TIMEZONE_OFFSET)
                    hour = local_now.strftime("%Y-%m-%d %H:00")
                    day = local_now.strftime("%Y-%m-%d")
                    await add_traffic_to_buffer(hour, day, flush, self.uid)
            return self.ok


def tune_socket(writer):
    sock = writer.get_extra_info('socket')
    if sock:
        import socket as _socket
        try:
            sock.setsockopt(_socket.IPPROTO_TCP, _socket.TCP_NODELAY, 1)
            sock.setsockopt(_socket.SOL_SOCKET, _socket.SO_SNDBUF, 2 * 1024 * 1024)
            sock.setsockopt(_socket.SOL_SOCKET, _socket.SO_RCVBUF, 2 * 1024 * 1024)
        except OSError:
            pass


def is_ip_allowed(link, uuid: str, ip: str) -> bool:
    if not link:
        return False
    limit = int(link.get('ip_limit', 0) or 0)
    if limit <= 0:
        return True
    current_ips = {c.get('ip') for c in connections.values() if c.get('uuid') == uuid}
    if tgproxy is not None:
        try:
            for s in tgproxy.active_proxy_sessions():
                if s.get('username') == uuid and s.get('client_ip'):
                    current_ips.add(s.get('client_ip'))
        except Exception:
            pass
    if ip in current_ips:
        return True
    return len(current_ips) < limit


async def parse_vless_header_extended(chunk: bytes):
    if len(chunk) < 24:
        raise ValueError("VLESS header too small")
    if chunk[0] != 0x00:
        raise ValueError("VLESS version not supported")
    pos = 1
    pos += 16
    addon_len = chunk[pos]; pos += 1 + addon_len
    if len(chunk) < pos + 3:
        raise ValueError("Malformed header")
    command = chunk[pos]; pos += 1
    port = int.from_bytes(chunk[pos:pos+2], "big"); pos += 2
    addr_type = chunk[pos]; pos += 1
    if addr_type == 1:
        if len(chunk) < pos + 4: raise ValueError("Incomplete IPv4")
        address = ".".join(str(b) for b in chunk[pos:pos+4]); pos += 4
    elif addr_type == 2:
        if len(chunk) < pos + 1: raise ValueError("Missing domain length")
        dlen = chunk[pos]; pos += 1
        if len(chunk) < pos + dlen: raise ValueError("Incomplete domain")
        address = chunk[pos:pos+dlen].decode("utf-8", errors="ignore"); pos += dlen
    elif addr_type == 3:
        if len(chunk) < pos + 16: raise ValueError("Incomplete IPv6")
        ab = chunk[pos:pos+16]; pos += 16
        address = ":".join(f"{ab[i]:02x}{ab[i+1]:02x}" for i in range(0, 16, 2))
    else:
        raise ValueError(f"Unknown address type: {addr_type}")
    return command, address, port, chunk[pos:]
async def parse_vless_header_with_uuid(chunk: bytes):
    if len(chunk) < 24:
        raise ValueError("VLESS header too small")
    if chunk[0] != 0x00:
        raise ValueError("VLESS version not supported")
    pos = 1
    uuid_bytes = chunk[pos:pos+16]
    uid = str(uuid_lib.UUID(bytes=uuid_bytes))
    pos += 16
    addon_len = chunk[pos]
    pos += 1 + addon_len
    if len(chunk) < pos + 3:
        raise ValueError("Malformed header")
    command = chunk[pos]; pos += 1
    port = int.from_bytes(chunk[pos:pos+2], "big"); pos += 2
    addr_type = chunk[pos]; pos += 1
    if addr_type == 1:
        if len(chunk) < pos + 4: raise ValueError("Incomplete IPv4")
        address = ".".join(str(b) for b in chunk[pos:pos+4]); pos += 4
    elif addr_type == 2:
        if len(chunk) < pos + 1: raise ValueError("Missing domain length")
        dlen = chunk[pos]; pos += 1
        if len(chunk) < pos + dlen: raise ValueError("Incomplete domain")
        address = chunk[pos:pos+dlen].decode("utf-8", errors="ignore"); pos += dlen
    elif addr_type == 3:
        if len(chunk) < pos + 16: raise ValueError("Incomplete IPv6")
        ab = chunk[pos:pos+16]; pos += 16
        address = ":".join(f"{ab[i]:02x}{ab[i+1]:02x}" for i in range(0, 16, 2))
    else:
        raise ValueError(f"Unknown address type: {addr_type}")
    return uid, command, address, port, chunk[pos:]


def vmess_kdf(key, *paths):
    h = hmac_mod.new(b"VMess AEAD KDF", paths[0], hashlib.sha256).digest()
    for p in paths[1:]:
        h = hmac_mod.new(h, p, hashlib.sha256).digest()
    return hmac_mod.new(h, key, hashlib.sha256).digest()


def vmess_cmd_key(uuid_bytes):
    return hashlib.md5(uuid_bytes + b"c48619fe-8f02-49e0-b9e9-edf763e17e21", usedforsecurity=False).digest()


def fnv1a32(data):
    h = 2166136261
    for b in data:
        h ^= b
        h = (h * 16777619) & 0xFFFFFFFF
    return h


def aes_ecb_encrypt(key, block):
    cipher = Cipher(AES(key), ECB())
    enc = cipher.encryptor()
    return enc.update(block) + enc.finalize()


def aes_ecb_decrypt(key, block):
    cipher = Cipher(AES(key), ECB())
    dec = cipher.decryptor()
    return dec.update(block) + dec.finalize()


def vmess_auth_id(cmd_key, timestamp=None, rand=None):
    ts = int(time.time()) if timestamp is None else int(timestamp)
    r = secrets.token_bytes(4) if rand is None else rand
    plain = struct.pack(">Q", ts) + r
    crc = zlib.crc32(plain) & 0xFFFFFFFF
    plain = plain + struct.pack(">I", crc)
    key = vmess_kdf(cmd_key, b"AES Auth ID Encryption")[:16]
    return aes_ecb_encrypt(key, plain)


def vmess_auth_id_decrypt(cmd_key, enc):
    key = vmess_kdf(cmd_key, b"AES Auth ID Encryption")[:16]
    plain = aes_ecb_decrypt(key, enc)
    ts = struct.unpack(">Q", plain[0:8])[0]
    r = plain[8:12]
    crc = struct.unpack(">I", plain[12:16])[0]
    if (zlib.crc32(plain[0:12]) & 0xFFFFFFFF) != crc:
        raise ValueError("VMess AuthID CRC mismatch")
    now = int(time.time())
    if abs(now - ts) > 120:
        raise ValueError("VMess AuthID timestamp out of window")
    return ts, r


def vmess_body_key_iv(sec, req_key, req_iv):
    if sec == 0x03:
        return req_key, req_iv
    if sec == 0x04:
        k = hashlib.md5(req_key, usedforsecurity=False).digest() + hashlib.md5(hashlib.md5(req_key, usedforsecurity=False).digest(), usedforsecurity=False).digest()
        return k, req_iv
    raise ValueError("unsupported VMess body cipher")


def vmess_seal_chunk(sec, key, iv, counter, plaintext):
    nonce = struct.pack(">H", counter & 0xFFFF) + iv[2:12]
    if sec == 0x03:
        ct = AESGCM(key).encrypt(nonce, plaintext, None)
    elif sec == 0x04:
        ct = ChaCha20Poly1305(key).encrypt(nonce, plaintext, None)
    else:
        raise ValueError("unsupported VMess body cipher")
    return struct.pack(">H", len(ct)) + ct


def vmess_open_chunk(sec, key, iv, counter, packet):
    nonce = struct.pack(">H", counter & 0xFFFF) + iv[2:12]
    if sec == 0x03:
        return AESGCM(key).decrypt(nonce, packet, None)
    if sec == 0x04:
        return ChaCha20Poly1305(key).decrypt(nonce, packet, None)
    raise ValueError("unsupported VMess body cipher")


class VMessRequest:
    def __init__(self):
        self.command = None
        self.address = None
        self.port = None
        self.req_key = None
        self.req_iv = None
        self.resp_v = None
        self.sec = None
        self.initial_payload = b""
        self.header_len = 0


def vmess_parse_request(buf, uuid_str):
    uid_bytes = uuid_lib.UUID(uuid_str).bytes
    cmd_key = vmess_cmd_key(uid_bytes)
    if len(buf) < 16 + 18 + 8:
        raise ValueError("VMess request too short")
    eauth = buf[0:16]
    ts, rand = vmess_auth_id_decrypt(cmd_key, eauth)
    enc_len = buf[16:34]
    nonce = buf[34:42]
    k_len = vmess_kdf(cmd_key, b"VMess Header AEAD Key_Length", eauth, nonce)[:16]
    n_len = vmess_kdf(cmd_key, b"VMess Header AEAD Nonce_Length", eauth, nonce)[:12]
    hlen = struct.unpack(">H", AESGCM(k_len).decrypt(n_len, enc_len, eauth))[0]
    if hlen < 44 or hlen > 512:
        raise ValueError("VMess header length out of range")
    enc_hdr = buf[42:42 + hlen + 16]
    if len(enc_hdr) < hlen + 16:
        raise ValueError("VMess header truncated")
    k_hdr = vmess_kdf(cmd_key, b"VMess Header AEAD Key", eauth, nonce)[:16]
    n_hdr = vmess_kdf(cmd_key, b"VMess Header AEAD Nonce", eauth, nonce)[:12]
    header = AESGCM(k_hdr).decrypt(n_hdr, enc_hdr, eauth)
    if header[0] != 0x01:
        raise ValueError("VMess version not supported")
    req = VMessRequest()
    req.req_iv = header[1:17]
    req.req_key = header[17:33]
    req.resp_v = header[33]
    opt = header[34]
    if opt != 0x01:
        raise ValueError("VMess options not supported")
    pad_sec = header[35]
    sec = pad_sec & 0x0F
    if sec not in (0x03, 0x04):
        raise ValueError("VMess body cipher not supported")
    req.sec = sec
    if header[36] != 0x00:
        raise ValueError("VMess reserved byte not zero")
    req.command = header[37]
    if req.command not in (0x01, 0x02):
        raise ValueError("VMess command not supported")
    req.port = struct.unpack(">H", header[38:40])[0]
    atype = header[40]
    pos = 41
    if atype == 0x01:
        req.address = ".".join(str(b) for b in header[pos:pos + 4])
        pos += 4
    elif atype == 0x02:
        dlen = header[pos]
        pos += 1
        req.address = header[pos:pos + dlen].decode("utf-8", errors="ignore")
        pos += dlen
    elif atype == 0x03:
        import ipaddress as _ip
        req.address = str(_ip.IPv6Address(header[pos:pos + 16]))
        pos += 16
    else:
        raise ValueError("VMess address type not supported")
    pad_len = (pad_sec >> 4) & 0x0F
    pos += pad_len
    expect_crc = struct.unpack(">I", header[pos:pos + 4])[0]
    if fnv1a32(header[:pos]) != expect_crc:
        raise ValueError("VMess header checksum mismatch")
    req.header_len = 42 + hlen + 16
    return req, ts, rand


def vmess_build_response(req):
    resp_key = hashlib.sha256(req.req_key).digest()[:16]
    resp_iv = hashlib.sha256(req.req_iv).digest()[:16]
    plain = bytes([req.resp_v, 0x00, 0x00, 0x00])
    k_len = vmess_kdf(resp_key, b"AEAD Resp Header Len Key")[:16]
    n_len = vmess_kdf(resp_iv, b"AEAD Resp Header Len IV")[:12]
    enc_len = AESGCM(k_len).encrypt(n_len, struct.pack(">H", len(plain)), None)
    k_hdr = vmess_kdf(resp_key, b"AEAD Resp Header Key")[:16]
    n_hdr = vmess_kdf(resp_iv, b"AEAD Resp Header IV")[:12]
    enc_hdr = AESGCM(k_hdr).encrypt(n_hdr, plain, None)
    return enc_len + enc_hdr, resp_key, resp_iv


def vmess_response_body_key_iv(sec, resp_key, resp_iv):
    if sec == 0x03:
        return resp_key, resp_iv
    if sec == 0x04:
        k = hashlib.md5(resp_key, usedforsecurity=False).digest() + hashlib.md5(hashlib.md5(resp_key, usedforsecurity=False).digest(), usedforsecurity=False).digest()
        return k, resp_iv
    raise ValueError("unsupported VMess body cipher")


def parse_socks_address(buf, pos, vmess_style=False):
    atype = buf[pos]
    pos += 1
    if atype == 0x01:
        addr = ".".join(str(b) for b in buf[pos:pos + 4])
        pos += 4
    elif atype == 0x03:
        dlen = buf[pos]
        pos += 1
        addr = buf[pos:pos + dlen].decode("utf-8", errors="ignore")
        pos += dlen
    elif atype == 0x04:
        addr = str(ipaddress.IPv6Address(buf[pos:pos + 16]))
        pos += 16
    else:
        raise ValueError("address type not supported")
    port = struct.unpack(">H", buf[pos:pos + 2])[0]
    pos += 2
    return addr, port, pos


def trojan_parse_request(buf, password):
    expect = hashlib.sha224(password.encode()).hexdigest().encode()
    if len(buf) < 58:
        raise ValueError("Trojan request too short")
    if not hmac_mod.compare_digest(buf[0:56], expect):
        raise ValueError("Trojan password mismatch")
    if buf[56:58] != b"\r\n":
        raise ValueError("Trojan header missing CRLF")
    pos = 58
    command = buf[pos]
    pos += 1
    if command not in (0x01, 0x03):
        raise ValueError("Trojan command not supported")
    address, port, pos = parse_socks_address(buf, pos)
    if buf[pos:pos + 2] != b"\r\n":
        raise ValueError("Trojan header missing trailing CRLF")
    pos += 2
    return command, address, port, buf[pos:]


SS2022_METHODS = {
    "2022-blake3-aes-128-gcm": (16, 16, "aes128"),
    "2022-blake3-aes-256-gcm": (32, 32, "aes256"),
    "2022-blake3-chacha20-poly1305": (32, 32, "chacha"),
}


SS_CLASSIC_METHODS = {
    "aes-128-gcm": (16, 16, "aes128"),
    "aes-256-gcm": (32, 32, "aes256"),
    "chacha20-poly1305": (32, 32, "chacha"),
}


def ss_key_len(method):
    if method in SS2022_METHODS:
        return SS2022_METHODS[method][0]
    if method in SS_CLASSIC_METHODS:
        return SS_CLASSIC_METHODS[method][0]
    raise ValueError("Shadowsocks method not supported")


def ss_salt_len(method):
    return ss_key_len(method)


def ss_aead_encrypt(method, key, nonce, plaintext):
    kind = SS2022_METHODS.get(method, SS_CLASSIC_METHODS.get(method))[2]
    if kind == "aes128" or kind == "aes256":
        return AESGCM(key).encrypt(nonce, plaintext, None)
    return ChaCha20Poly1305(key).encrypt(nonce, plaintext, None)


def ss_aead_decrypt(method, key, nonce, ciphertext):
    kind = SS2022_METHODS.get(method, SS_CLASSIC_METHODS.get(method))[2]
    if kind == "aes128" or kind == "aes256":
        return AESGCM(key).decrypt(nonce, ciphertext, None)
    return ChaCha20Poly1305(key).decrypt(nonce, ciphertext, None)


def ss_derive_subkey_2022(psk, salt, key_len):
    if not HAS_BLAKE3:
        raise RuntimeError("Shadowsocks 2022 needs the blake3 package")
    return blake3_mod.blake3(psk + salt, derive_key_context="shadowsocks 2022 session subkey").digest()[:key_len]


def ss_derive_subkey_classic(psk, salt):
    klen = len(psk)
    hkdf = HKDF(algorithm=hashes.SHA1(), length=klen, salt=salt, info=b"ss-subkey")
    return hkdf.derive(psk)


def ss_derive_subkey(method, psk, salt):
    if method in SS2022_METHODS:
        return ss_derive_subkey_2022(psk, salt, ss_key_len(method))
    return ss_derive_subkey_classic(psk, salt)


class SSChunkStream:
    def __init__(self, method, subkey):
        self.method = method
        self.subkey = subkey
        self.nonce_counter = 0
        self.buf = bytearray()
        self.pending_len = None

    def nonce(self):
        n = struct.pack("<Q", self.nonce_counter) + b"\x00\x00\x00\x00"
        self.nonce_counter += 1
        return n

    def seal_chunk(self, plaintext):
        return ss_aead_encrypt(self.method, self.subkey, self.nonce(), plaintext)

    def open_chunk(self, ciphertext):
        return ss_aead_decrypt(self.method, self.subkey, self.nonce(), ciphertext)

    def feed(self, data):
        self.buf += data

    def read_exact(self, n):
        if len(self.buf) < n:
            return None
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out

    def read_chunk(self):
        if self.pending_len is None:
            raw_len = self.read_exact(18)
            if raw_len is None:
                return None
            try:
                plain_len = self.open_chunk(raw_len)
            except Exception:
                raise ValueError("Shadowsocks length chunk failed")
            self.pending_len = struct.unpack(">H", plain_len)[0]
        raw = self.read_exact(self.pending_len + 16)
        if raw is None:
            return None
        length = self.pending_len
        self.pending_len = None
        try:
            return self.open_chunk(raw)
        except Exception:
            raise ValueError("Shadowsocks payload chunk failed")


class WSByteReader:
    def __init__(self, websocket, initial=b""):
        self.websocket = websocket
        self.buf = bytearray(initial or b"")
        self.closed = False

    async def read_exact(self, n):
        while len(self.buf) < n:
            msg = await self.websocket.receive()
            if msg["type"] == "websocket.disconnect":
                self.closed = True
                return None
            data = msg.get("bytes") or (msg.get("text") or "").encode()
            if data:
                self.buf += data
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out

    async def read_some(self):
        if self.buf:
            out = bytes(self.buf)
            self.buf.clear()
            return out
        msg = await self.websocket.receive()
        if msg["type"] == "websocket.disconnect":
            self.closed = True
            return None
        return msg.get("bytes") or (msg.get("text") or "").encode()


async def stable_account(uid, conn_id, n, gate, direction):
    if gate:
        await gate.add(n)
        if not await gate.check():
            return False
    else:
        if not await consume_quota(uid, n):
            return False
    stats["total_bytes"] += n
    if direction == "up":
        stats["upload_bytes"] += n
    else:
        stats["download_bytes"] += n
    async with connections_lock:
        if conn_id in connections:
            connections[conn_id]["bytes"] += n
            if direction == "up":
                connections[conn_id]["bytes_up"] = connections[conn_id].get("bytes_up", 0) + n
            else:
                connections[conn_id]["bytes_down"] = connections[conn_id].get("bytes_down", 0) + n
            if gate is not None:
                connections[conn_id]["quota_gate"] = gate
    return True


async def stable_ws_to_tcp_raw(websocket, writer, conn_id, uid, gate, first_payload=b""):
    try:
        if first_payload:
            if not await stable_account(uid, conn_id, len(first_payload), gate, "up"):
                return
            writer.write(first_payload)
            await writer.drain()
        while True:
            msg = await websocket.receive()
            if msg["type"] == "websocket.disconnect":
                break
            data = msg.get("bytes") or (msg.get("text") or "").encode()
            if not data:
                continue
            if not await stable_account(uid, conn_id, len(data), gate, "up"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                break
            try:
                writer.write(data)
                await writer.drain()
            except Exception:
                break
    except WebSocketDisconnect:
        pass
    except Exception as exc:
        logger.error(f"stable ws_to_tcp error {conn_id}: {exc}", exc_info=True)
    finally:
        try:
            if writer and not writer.is_closing():
                writer.write_eof()
        except Exception:
            pass


async def stable_tcp_to_ws_raw(websocket, reader, conn_id, uid, gate):
    try:
        while True:
            data = await reader.read(RELAY_BUF)
            if not data:
                break
            if not await stable_account(uid, conn_id, len(data), gate, "down"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                break
            try:
                await websocket.send_bytes(data)
            except Exception:
                break
    except Exception as exc:
        logger.error(f"stable tcp_to_ws error {conn_id}: {exc}", exc_info=True)


async def handle_trojan_ws(websocket, link, uuid, client_ip, conn_id, first_chunk):
    reader = WSByteReader(websocket, first_chunk)
    head = await reader.read_exact(60)
    if head is None:
        await websocket.close(code=1002, reason="invalid request")
        return
    try:
        expect = hashlib.sha224(str(uuid).encode()).hexdigest().encode()
        if not secrets.compare_digest(head[0:56], expect):
            raise ValueError("Trojan password mismatch")
        if head[56:58] != b"\r\n":
            raise ValueError("Trojan header missing CRLF")
        command = head[58]
        if command not in (0x01, 0x03):
            raise ValueError("Trojan command not supported")
        atyp = head[59]
        if atyp == 0x01:
            tail = await reader.read_exact(8)
            if tail is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            full = head + tail
        elif atyp == 0x04:
            tail = await reader.read_exact(20)
            if tail is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            full = head + tail
        elif atyp == 0x03:
            dlen_byte = await reader.read_exact(1)
            if dlen_byte is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            tail = await reader.read_exact(dlen_byte[0] + 4)
            if tail is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            full = head + dlen_byte + tail
        else:
            raise ValueError("Trojan address type not supported")
        pos = 58
        command = full[pos]
        pos += 1
        address, port, pos = parse_socks_address(full, pos)
        if full[pos:pos + 2] != b"\r\n":
            raise ValueError("Trojan header missing trailing CRLF")
        pos += 2
        initial_payload = full[pos:]
    except ValueError:
        await websocket.close(code=1008, reason="invalid header")
        return
    if is_domain_blocked_for_link(address, link):
        await websocket.close(code=1008, reason="blocked domain")
        return
    validated, validated_ips = await validate_tunnel_target(address, via_proxy=bool(link and (link.get("proxy_line_id") or (link.get("outbound_proxy") or "").strip())))
    if not validated:
        await websocket.close(code=1008, reason="access to private network denied")
        return
    gate = QuotaGate(uuid)
    if initial_payload:
        await gate.add(len(initial_payload))
        if not await gate.check():
            await websocket.close(code=1008, reason="quota exceeded")
            return
    if command == 0x03:
        if not link.get("udp_enabled", True):
            await websocket.close(code=1008, reason="udp disabled")
            return
        leftover = bytes(reader.buf)
        reader.buf.clear()
        first_data = initial_payload + leftover
        stats["total_requests"] += 1
        await _trojan_udp_session(websocket, conn_id, uuid, gate, first_data, link)
        return
    try:
        reader2, writer = await open_validated_connection(address, port, link, validated_ips)
    except Exception:
        await websocket.close(code=1011, reason="upstream failed")
        return
    tune_socket_for_link(writer, link)
    await _record_destination(conn_id, address, port)
    stats["total_requests"] += 1
    leftover = bytes(reader.buf)
    reader.buf.clear()
    if leftover:
        initial_payload = initial_payload + leftover
    up_task = asyncio.create_task(stable_ws_to_tcp_raw(websocket, writer, conn_id, uuid, gate, first_payload=initial_payload))
    down_task = asyncio.create_task(stable_tcp_to_ws_raw(websocket, reader2, conn_id, uuid, gate))
    done, pending = await asyncio.wait({up_task, down_task}, return_when=asyncio.FIRST_COMPLETED)
    for t in pending:
        t.cancel()
    try:
        writer.close()
        await writer.wait_closed()
    except Exception:
        pass


async def stable_vmess_upstream(reader, writer, conn_id, uid, gate, sec, key, iv):
    buf = bytearray()
    counter = 0
    try:
        while True:
            while len(buf) < 2:
                more = await reader.read_some()
                if more is None:
                    return
                buf += more
            ln = struct.unpack(">H", bytes(buf[0:2]))[0]
            del buf[0:2]
            while len(buf) < ln:
                more = await reader.read_some()
                if more is None:
                    return
                buf += more
            packet = bytes(buf[:ln])
            del buf[:ln]
            try:
                plain = vmess_open_chunk(sec, key, iv, counter, packet)
            except Exception:
                return
            counter += 1
            if not plain:
                try:
                    writer.write_eof()
                except Exception:
                    pass
                continue
            if not await stable_account(uid, conn_id, len(plain), gate, "up"):
                return
            try:
                writer.write(plain)
                await writer.drain()
            except Exception:
                return
    except Exception as exc:
        logger.error(f"vmess upstream error {conn_id}: {exc}", exc_info=True)
    finally:
        try:
            if writer and not writer.is_closing():
                writer.write_eof()
        except Exception:
            pass


async def stable_vmess_downstream(websocket, reader, conn_id, uid, gate, sec, key, iv):
    counter = 0
    try:
        while True:
            data = await reader.read(16384)
            if not data:
                try:
                    await websocket.send_bytes(vmess_seal_chunk(sec, key, iv, counter, b""))
                except Exception:
                    pass
                return
            if not await stable_account(uid, conn_id, len(data), gate, "down"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                return
            try:
                await websocket.send_bytes(vmess_seal_chunk(sec, key, iv, counter, data))
            except Exception:
                return
            counter += 1
    except Exception as exc:
        logger.error(f"vmess downstream error {conn_id}: {exc}", exc_info=True)


async def stable_vmess_udp_upstream(reader, udp_sock, conn_id, uid, gate, sec, key, iv):
    buf = bytearray()
    counter = 0
    loop = asyncio.get_event_loop()
    try:
        while True:
            while len(buf) < 2:
                more = await reader.read_some()
                if more is None:
                    return
                buf += more
            ln = struct.unpack(">H", bytes(buf[0:2]))[0]
            del buf[0:2]
            while len(buf) < ln:
                more = await reader.read_some()
                if more is None:
                    return
                buf += more
            packet = bytes(buf[:ln])
            del buf[:ln]
            try:
                plain = vmess_open_chunk(sec, key, iv, counter, packet)
            except Exception:
                return
            counter += 1
            if not plain:
                continue
            if not await stable_account(uid, conn_id, len(plain), gate, "up"):
                return
            try:
                await loop.sock_sendall(udp_sock, plain)
            except Exception:
                return
    except Exception as exc:
        logger.error(f"vmess udp upstream error {conn_id}: {exc}", exc_info=True)


async def stable_vmess_udp_downstream(websocket, udp_sock, conn_id, uid, gate, sec, key, iv):
    counter = 0
    loop = asyncio.get_event_loop()
    try:
        while True:
            data = await loop.sock_recv(udp_sock, 65535)
            if not data:
                continue
            if not await stable_account(uid, conn_id, len(data), gate, "down"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                return
            try:
                await websocket.send_bytes(vmess_seal_chunk(sec, key, iv, counter, data))
            except Exception:
                return
            counter += 1
    except Exception as exc:
        logger.error(f"vmess udp downstream error {conn_id}: {exc}", exc_info=True)


async def handle_vmess_ws(websocket, link, uuid, client_ip, conn_id, first_chunk):
    reader = WSByteReader(websocket, first_chunk)
    head = await reader.read_exact(42)
    if head is None:
        await websocket.close(code=1002, reason="invalid request")
        return
    try:
        uid_bytes = uuid_lib.UUID(uuid).bytes
        cmd_key = vmess_cmd_key(uid_bytes)
        eauth = head[0:16]
        enc_len = head[16:34]
        nonce = head[34:42]
        k_len = vmess_kdf(cmd_key, b"VMess Header AEAD Key_Length", eauth, nonce)[:16]
        n_len = vmess_kdf(cmd_key, b"VMess Header AEAD Nonce_Length", eauth, nonce)[:12]
        hlen = struct.unpack(">H", AESGCM(k_len).decrypt(n_len, enc_len, eauth))[0]
        if hlen < 44 or hlen > 512:
            raise ValueError("VMess header length out of range")
        rest = await reader.read_exact(hlen + 16)
        if rest is None:
            await websocket.close(code=1002, reason="invalid request")
            return
        req, ts, rand = vmess_parse_request(head + rest, uuid)
    except Exception:
        await websocket.close(code=1002, reason="invalid header")
        return
    now = time.time()
    for k in [k for k, v in _VMESS_REPLAY.items() if now - v > 180]:
        del _VMESS_REPLAY[k]
    replay_key = (ts, rand.hex())
    if replay_key in _VMESS_REPLAY:
        await websocket.close(code=1008, reason="replay rejected")
        return
    _VMESS_REPLAY[replay_key] = now
    if req.command not in (0x01, 0x02):
        await websocket.close(code=1008, reason="command not supported")
        return
    if is_domain_blocked_for_link(req.address, link):
        await websocket.close(code=1008, reason="blocked domain")
        return
    validated, validated_ips = await validate_tunnel_target(req.address, via_proxy=bool(link and (link.get("proxy_line_id") or (link.get("outbound_proxy") or "").strip())))
    if not validated:
        await websocket.close(code=1008, reason="access to private network denied")
        return
    await _record_destination(conn_id, req.address, req.port)
    gate = QuotaGate(uuid)
    if req.command == 0x02:
        if not link.get("udp_enabled", True):
            await websocket.close(code=1008, reason="udp disabled")
            return
        try:
            resp_hdr, resp_key, resp_iv = vmess_build_response(req)
            await websocket.send_bytes(resp_hdr)
        except Exception:
            await websocket.close(code=1011, reason="response failed")
            return
        body_key, body_iv = vmess_body_key_iv(req.sec, req.req_key, req.req_iv)
        rkey, riv = vmess_response_body_key_iv(req.sec, resp_key, resp_iv)
        stats["total_requests"] += 1
        try:
            udp_sock = await _open_udp_socket(req.address, req.port)
        except Exception:
            await websocket.close(code=1011, reason="upstream failed")
            return
        up_task = asyncio.create_task(stable_vmess_udp_upstream(reader, udp_sock, conn_id, uuid, gate, req.sec, body_key, body_iv))
        down_task = asyncio.create_task(stable_vmess_udp_downstream(websocket, udp_sock, conn_id, uuid, gate, req.sec, rkey, riv))
        done, pending = await asyncio.wait({up_task, down_task}, return_when=asyncio.FIRST_COMPLETED)
        for t in pending:
            t.cancel()
        try:
            udp_sock.close()
        except Exception:
            pass
        return
    try:
        reader2, writer = await open_validated_connection(req.address, req.port, link, validated_ips)
    except Exception:
        await websocket.close(code=1011, reason="upstream failed")
        return
    tune_socket_for_link(writer, link)
    stats["total_requests"] += 1
    try:
        resp_hdr, resp_key, resp_iv = vmess_build_response(req)
        await websocket.send_bytes(resp_hdr)
    except Exception:
        await websocket.close(code=1011, reason="response failed")
        return
    body_key, body_iv = vmess_body_key_iv(req.sec, req.req_key, req.req_iv)
    rkey, riv = vmess_response_body_key_iv(req.sec, resp_key, resp_iv)
    up_task = asyncio.create_task(stable_vmess_upstream(reader, writer, conn_id, uuid, gate, req.sec, body_key, body_iv))
    down_task = asyncio.create_task(stable_vmess_downstream(websocket, reader2, conn_id, uuid, gate, req.sec, rkey, riv))
    done, pending = await asyncio.wait({up_task, down_task}, return_when=asyncio.FIRST_COMPLETED)
    for t in pending:
        t.cancel()
    try:
        writer.close()
        await writer.wait_closed()
    except Exception:
        pass


async def stable_ss_upstream(reader, stream, writer, conn_id, uid, gate):
    try:
        while True:
            while True:
                try:
                    plain = stream.read_chunk()
                except ValueError:
                    return
                if plain is None:
                    break
                if not await stable_account(uid, conn_id, len(plain), gate, "up"):
                    return
                try:
                    writer.write(plain)
                    await writer.drain()
                except Exception:
                    return
            more = await reader.read_some()
            if more is None:
                return
            if more:
                stream.feed(more)
    except Exception as exc:
        logger.error(f"ss upstream error {conn_id}: {exc}", exc_info=True)
    finally:
        try:
            if writer and not writer.is_closing():
                writer.write_eof()
        except Exception:
            pass


async def stable_ss_downstream_2022(websocket, reader, conn_id, uid, gate, method, psk, req_salt):
    try:
        first = await reader.read(65535)
        resp_salt = secrets.token_bytes(ss_key_len(method))
        resp_sub = ss_derive_subkey(method, psk, resp_salt)
        resp_stream = SSChunkStream(method, resp_sub)
        first_len = len(first) if first else 0
        fixed = b"\x01" + struct.pack(">Q", int(time.time())) + req_salt + struct.pack(">H", first_len)
        out = bytearray()
        out += resp_salt
        out += resp_stream.seal_chunk(fixed)
        if first:
            if not await stable_account(uid, conn_id, len(first), gate, "down"):
                return
            out += resp_stream.seal_chunk(first)
        try:
            await websocket.send_bytes(bytes(out))
        except Exception:
            return
        if not first:
            return
        while True:
            data = await reader.read(65535)
            if not data:
                return
            if not await stable_account(uid, conn_id, len(data), gate, "down"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                return
            try:
                await websocket.send_bytes(resp_stream.seal_chunk(struct.pack(">H", len(data))) + resp_stream.seal_chunk(data))
            except Exception:
                return
    except Exception as exc:
        logger.error(f"ss downstream error {conn_id}: {exc}", exc_info=True)


async def stable_ss_downstream_classic(websocket, reader, conn_id, uid, gate, method, psk):
    try:
        resp_salt = secrets.token_bytes(ss_key_len(method))
        resp_sub = ss_derive_subkey(method, psk, resp_salt)
        resp_stream = SSChunkStream(method, resp_sub)
        try:
            await websocket.send_bytes(resp_salt)
        except Exception:
            return
        while True:
            data = await reader.read(16383)
            if not data:
                return
            if not await stable_account(uid, conn_id, len(data), gate, "down"):
                try:
                    await websocket.close(code=1008, reason="quota exceeded")
                except Exception:
                    pass
                return
            try:
                await websocket.send_bytes(resp_stream.seal_chunk(struct.pack(">H", len(data))) + resp_stream.seal_chunk(data))
            except Exception:
                return
    except Exception as exc:
        logger.error(f"ss downstream error {conn_id}: {exc}", exc_info=True)


async def handle_ss_ws(websocket, link, uuid, client_ip, conn_id, first_chunk):
    method = (link.get("ss_method") or "2022-blake3-aes-256-gcm")
    if method not in SS_METHODS:
        method = "2022-blake3-aes-256-gcm"
    if method in SS_2022_METHODS and not HAS_BLAKE3:
        await websocket.close(code=1008, reason="shadowsocks 2022 unavailable")
        return
    psk = ss_psk_for_link(link, method)
    klen = ss_key_len(method)
    reader = WSByteReader(websocket, first_chunk)
    salt = await reader.read_exact(klen)
    if salt is None:
        await websocket.close(code=1002, reason="invalid request")
        return
    is_2022 = method in SS_2022_METHODS
    if is_2022:
        now = time.time()
        for k in [k for k, v in _SS_SALTS.items() if now - v > 60]:
            del _SS_SALTS[k]
        if salt in _SS_SALTS:
            await websocket.close(code=1008, reason="replay rejected")
            return
        _SS_SALTS[salt] = now
    try:
        subkey = ss_derive_subkey(method, psk, salt)
    except Exception:
        await websocket.close(code=1008, reason="shadowsocks unavailable")
        return
    stream = SSChunkStream(method, subkey)
    try:
        if is_2022:
            fixed_ct = await reader.read_exact(27)
            if fixed_ct is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            fixed = stream.open_chunk(fixed_ct)
            if fixed[0] != 0x00:
                raise ValueError("SS header type not supported")
            ts = struct.unpack(">Q", fixed[1:9])[0]
            if abs(int(time.time()) - ts) > 30:
                raise ValueError("SS timestamp out of window")
            var_len = struct.unpack(">H", fixed[9:11])[0]
            var_ct = await reader.read_exact(var_len + 16)
            if var_ct is None:
                await websocket.close(code=1002, reason="invalid request")
                return
            var = stream.open_chunk(var_ct)
            address, port, pos = parse_socks_address(var, 0)
            pad_len = struct.unpack(">H", var[pos:pos + 2])[0]
            pos += 2 + pad_len
            initial_payload = var[pos:]
        else:
            first = None
            while first is None:
                try:
                    first = stream.read_chunk()
                except ValueError:
                    raise
                if first is not None:
                    break
                more = await reader.read_some()
                if more is None:
                    await websocket.close(code=1002, reason="invalid request")
                    return
                if more:
                    stream.feed(more)
            address, port, pos = parse_socks_address(first, 0)
            initial_payload = first[pos:]
    except ValueError:
        await websocket.close(code=1002, reason="invalid header")
        return
    except Exception:
        await websocket.close(code=1002, reason="invalid header")
        return
    if is_domain_blocked_for_link(address, link):
        await websocket.close(code=1008, reason="blocked domain")
        return
    validated, validated_ips = await validate_tunnel_target(address, via_proxy=bool(link and (link.get("proxy_line_id") or (link.get("outbound_proxy") or "").strip())))
    if not validated:
        await websocket.close(code=1008, reason="access to private network denied")
        return
    await _record_destination(conn_id, address, port)
    gate = QuotaGate(uuid)
    if initial_payload:
        await gate.add(len(initial_payload))
        if not await gate.check():
            await websocket.close(code=1008, reason="quota exceeded")
            return
    try:
        reader2, writer = await open_validated_connection(address, port, link, validated_ips)
    except Exception:
        await websocket.close(code=1011, reason="upstream failed")
        return
    tune_socket_for_link(writer, link)
    stats["total_requests"] += 1
    if initial_payload:
        try:
            writer.write(initial_payload)
            await writer.drain()
        except Exception:
            await websocket.close(code=1011, reason="upstream failed")
            return
    if reader.buf:
        stream.feed(bytes(reader.buf))
        reader.buf.clear()
    up_task = asyncio.create_task(stable_ss_upstream(reader, stream, writer, conn_id, uuid, gate))
    if is_2022:
        down_task = asyncio.create_task(stable_ss_downstream_2022(websocket, reader2, conn_id, uuid, gate, method, psk, salt))
    else:
        down_task = asyncio.create_task(stable_ss_downstream_classic(websocket, reader2, conn_id, uuid, gate, method, psk))
    done, pending = await asyncio.wait({up_task, down_task}, return_when=asyncio.FIRST_COMPLETED)
    for t in pending:
        t.cancel()
    try:
        writer.close()
        await writer.wait_closed()
    except Exception:
        pass


def generate_vmess_link(uid, remark="SulgX", address=None, extra=None, server_domain=None):
    domain = server_domain or get_domain()
    addr = address if address else domain
    path = get_effective_path(extra) if extra else DEFAULT_PATH
    path = path.replace("{uid}", uid)
    if extra and extra.get("random_path", False):
        path = "/" + secrets.token_hex(4) + path
    sni = (extra.get("custom_sni") or domain) if extra else domain
    host = (extra.get("custom_host") or domain) if extra else domain
    fingerprint = (extra.get("fingerprint") or extra.get("custom_fp") or "chrome") if extra else "chrome"
    if not fingerprint or fingerprint.lower() == "none":
        fingerprint = ""
    fingerprint = ech_safe_fingerprint(extra, fingerprint)
    alpn = effective_alpn(extra) or ""
    port = extra.get("port", 443) if extra else 443
    scy = vmess_security_for_link(extra)
    node = {
        "v": "2", "ps": remark, "add": addr, "port": str(port), "id": uid,
        "aid": "0", "scy": scy, "net": "ws", "type": "none",
        "host": host, "path": path, "tls": "tls", "sni": sni,
    }
    if fingerprint:
        node["fp"] = fingerprint
    if alpn:
        node["alpn"] = alpn
    encoded = base64.b64encode(json.dumps(node, separators=(",", ":")).encode()).decode()
    return "vmess://" + encoded


def generate_trojan_link(uid, remark="SulgX", address=None, extra=None, server_domain=None):
    domain = server_domain or get_domain()
    addr = address if address else domain
    path = get_effective_path(extra) if extra else DEFAULT_PATH
    path = path.replace("{uid}", uid)
    if extra and extra.get("random_path", False):
        path = "/" + secrets.token_hex(4) + path
    sni = (extra.get("custom_sni") or domain) if extra else domain
    host = (extra.get("custom_host") or domain) if extra else domain
    fingerprint = (extra.get("fingerprint") or extra.get("custom_fp") or "chrome") if extra else "chrome"
    if not fingerprint or fingerprint.lower() == "none":
        fingerprint = ""
    fingerprint = ech_safe_fingerprint(extra, fingerprint)
    alpn = effective_alpn(extra) or ""
    port = extra.get("port", 443) if extra else 443
    fragment = fragment_spec_for_link(extra) if extra else ""
    allow_insecure = extra.get("allow_insecure", False) if extra else False
    params = {
        "type": "ws", "security": "tls", "sni": sni, "host": host,
        "path": path,
    }
    if fingerprint:
        params["fp"] = fingerprint
    if alpn:
        params["alpn"] = alpn
    if allow_insecure:
        params["allowInsecure"] = "1"
    else:
        params["allowInsecure"] = "0"
    if fragment:
        params["fragment"] = fragment
    _ech_value = ech_config_list_value(extra)
    if _ech_value:
        params["ech"] = _ech_value
    query = "&".join(f"{k}={quote(str(v))}" for k, v in params.items())
    return f"trojan://{uid}@{format_host_port(addr, port)}?{query}#{quote(remark)}"


def generate_ss_link(uid, remark="SulgX", address=None, extra=None, server_domain=None):
    domain = server_domain or get_domain()
    addr = address if address else domain
    path = get_effective_path(extra) if extra else DEFAULT_PATH
    path = path.replace("{uid}", uid)
    if extra and extra.get("random_path", False):
        path = "/" + secrets.token_hex(4) + path
    sni = (extra.get("custom_sni") or domain) if extra else domain
    host = (extra.get("custom_host") or domain) if extra else domain
    port = extra.get("port", 443) if extra else 443
    method = (extra.get("ss_method") or "2022-blake3-aes-256-gcm") if extra else "2022-blake3-aes-256-gcm"
    if method not in SS_METHODS:
        method = "2022-blake3-aes-256-gcm"
    plugin = "v2ray-plugin;mode=websocket;host=" + host + ";path=" + path + ";tls;mux=0"
    plugin_enc = quote(plugin, safe="")
    if method in SS_2022_METHODS:
        psk_bytes = ss_psk_for_link(extra or {"uid": uid}, method)
        psk_b64 = base64.b64encode(psk_bytes).decode()
        userinfo = ss_client_method(method) + ":" + quote(psk_b64, safe="")
        return f"ss://{userinfo}@{format_host_port(addr, port)}/?plugin={plugin_enc}#{quote(remark)}"
    userinfo_raw = ss_client_method(method) + ":" + uid
    userinfo = base64.urlsafe_b64encode(userinfo_raw.encode()).decode().rstrip("=")
    return f"ss://{userinfo}@{format_host_port(addr, port)}/?plugin={plugin_enc}#{quote(remark)}"



def _webproxy_conflict(port, exclude_uid=""):
    if int(port) == int(WEBPROXY_PUBLIC_PORT):
        return None
    for _l in LINKS.values():
        if (_l.get("protocol") or "") == "webproxy" and _l.get("active") and int(_l.get("port") or 443) == int(port) and _l.get("uid") != exclude_uid:
            return _l
    return None


def _webproxy_valid_token(value):
    text = str(value or "").strip().lower()
    return len(text) == 12 and all(c in "0123456789abcdef" for c in text)


def _webproxy_token_conflict(token, exclude_uid=""):
    token = str(token or "").strip().lower()
    if not token:
        return None
    for _l in LINKS.values():
        if (_l.get("protocol") or "") == "webproxy" and str(_l.get("webproxy_token") or "").strip().lower() == token and _l.get("uid") != exclude_uid:
            return _l
    return None


def _webproxy_secret_conflict(secret_hex, exclude_uid=""):
    secret_hex = str(secret_hex or "").strip().lower()
    if secret_hex.startswith("dd"):
        secret_hex = secret_hex[2:]
    if not secret_hex:
        return None
    for _l in LINKS.values():
        if (_l.get("protocol") or "") == "webproxy" and str(_l.get("uid", "")) != str(exclude_uid or ""):
            if _web_secret_hex_or_empty(_l) == secret_hex:
                return _l
    return None


def _webproxy_new_token(exclude_uid=""):
    for _attempt in range(64):
        token = secrets.token_hex(6)
        if _webproxy_token_conflict(token, exclude_uid) is None:
            return token
    raise RuntimeError("could not allocate a unique WEB proxy token")


def _parse_proxy_port(raw, protocol):
    if raw is None or raw == "":
        return int(PROXY_DEFAULT_PORTS.get(protocol, 443))
    try:
        value = _parse_int_value(raw, "port", 0, 1, 65535)
    except HTTPException:
        raise HTTPException(status_code=400, detail="Proxy port must be an integer between 1 and 65535")
    return value


def _panel_listen_port():
    try:
        return int(os.environ.get("PORT", CONFIG.get("port", 8000)) or 0)
    except (TypeError, ValueError):
        return 0


def _web_port_is_fronted(port):
    try:
        wanted = int(port or 0)
    except (TypeError, ValueError):
        return False
    if not wanted:
        return False
    if wanted == int(WEBPROXY_PUBLIC_PORT):
        return True
    if wanted == _panel_listen_port():
        return True
    return wanted in _mux_ports_in_use()


def _mux_ports_in_use(exclude_uid="", links=None):
    ports = set()
    for _env_port in (SOCKS_PORT, TG_PROXY_PORT, HTTP_PROXY_PORT):
        try:
            if int(_env_port or 0):
                ports.add(int(_env_port))
        except (TypeError, ValueError):
            continue
    rows = list(links) if links is not None else list(LINKS.values())
    for _l in rows:
        if (_l.get("protocol") or "") not in MUX_PROTOCOLS:
            continue
        if not _l.get("active"):
            continue
        if str(_l.get("uid") or "") == str(exclude_uid or ""):
            continue
        try:
            _p = int(_l.get("port") or 0)
        except (TypeError, ValueError):
            continue
        if _p:
            ports.add(_p)
    return ports


def _proxy_port_conflict(port, protocol, exclude_uid="", links=None):
    try:
        wanted = int(port)
    except (TypeError, ValueError):
        return None
    if not wanted:
        return None
    if protocol in MUX_PROTOCOLS:
        if wanted == _panel_listen_port():
            return {"label": "panel web server", "uid": "panel", "protocol": "panel", "kind": "panel"}
    return None


def _proxy_port_conflict_detail(port, protocol, conflict):
    return "Proxy port " + str(port) + " cannot be used for " + str(protocol) + ": the panel web server already listens on port " + str(port) + ", and the proxy multiplexer needs its own listener on that port. Restart the panel with the panel on an internal port (set PORT to an internal port such as 8000 and PANEL_BIND_HOST to 127.0.0.1), then create this inbound on port " + str(port) + ": the multiplexer will own port " + str(port) + " and forward panel, WebSocket and WEB proxy traffic to the panel."


def _proxy_username_conflict(username, exclude_uid="", links=None):
    wanted = str(username or "").strip()
    if not wanted:
        return None
    rows = list(links) if links is not None else list(LINKS.values())
    for _l in rows:
        if str(_l.get("uid") or "") == str(exclude_uid or ""):
            continue
        if str(_l.get("uid") or "") == wanted:
            return _l
        if (_l.get("protocol") or "") in ("socks5", "http-proxy") and str(_l.get("proxy_username") or "").strip() == wanted:
            return _l
    return None


def _proxy_username_conflict_detail(username, conflict):
    return "Proxy username '" + str(username) + "' is already used by inbound '" + str(conflict.get("label", "")) + "' (" + str(conflict.get("uid", "")) + ", " + str(conflict.get("protocol", "")) + "). SOCKS5 and HTTP proxy logins share one credential namespace on every shared port, so each username must be unique, and it must not equal another inbound UUID. Choose a different username."


def _ws_effective_path(uid, custom_path):
    raw = str(custom_path or "").strip()
    if raw:
        return raw.replace("{uid}", str(uid))
    return str(DEFAULT_PATH or "/ws/{uid}").replace("{uid}", str(uid))


def _ws_path_routes_to_uid(uid, custom_path):
    eff = _ws_effective_path(uid, custom_path)
    parts = [p for p in eff.strip("/").split("/") if p]
    return bool(parts) and parts[-1] == str(uid)


def _ws_path_conflict(uid, protocol, custom_path, exclude_uid="", links=None):
    if (protocol or "") not in WS_PROTOCOLS:
        return None
    mine = _ws_effective_path(uid, custom_path)
    rows = list(links) if links is not None else list(LINKS.values())
    for _l in rows:
        if (_l.get("protocol") or "") not in WS_PROTOCOLS:
            continue
        if not _l.get("active"):
            continue
        if str(_l.get("uid") or "") == str(exclude_uid or ""):
            continue
        other = _ws_effective_path(str(_l.get("uid") or ""), str(_l.get("custom_path") or ""))
        if other == mine:
            return _l
    return None


def _ws_path_conflict_detail(uid, custom_path, conflict):
    return "WebSocket path '" + _ws_effective_path(uid, custom_path) + "' is already used by inbound '" + str(conflict.get("label", "")) + "' (" + str(conflict.get("uid", "")) + ", " + str(conflict.get("protocol", "")) + "). All WebSocket inbounds share the panel port and are routed by path, so each inbound needs a different path. Use a custom path containing {uid}."


def _webproxy_shared_443():
    count = 0
    for _l in LINKS.values():
        if (_l.get("protocol") or "") == "webproxy" and _l.get("active") and int(_l.get("port") or 443) == int(WEBPROXY_PUBLIC_PORT):
            count += 1
    return count > 1


def _webproxy_port_in_use(port, exclude_uid=""):
    return _webproxy_conflict(port, exclude_uid) is not None


def _next_free_webproxy_port(exclude_uid=""):
    for _p in _webproxy_allowed_ports():
        if not _webproxy_port_in_use(_p, exclude_uid):
            return _p
    return 0


_PUBLISHED_PORT_ENV = {"socks5": "PUBLISHED_SOCKS_PORT", "mtproto": "PUBLISHED_MTPROTO_PORT", "http-proxy": "PUBLISHED_HTTP_PORT"}


def _declared_published_port(link):
    protocol = (link or {}).get("protocol") or ""
    env_name = _PUBLISHED_PORT_ENV.get(protocol)
    if not env_name:
        return None
    raw = (os.environ.get(env_name) or "").strip()
    if not raw:
        return None
    try:
        if ":" in raw:
            public_s, container_s = raw.split(":", 1)
            public_port = int(public_s)
            container_port = int(container_s)
        else:
            public_port = int(raw)
            container_port = public_port
    except (TypeError, ValueError):
        return None
    if public_port <= 0 or public_port > 65535 or container_port <= 0 or container_port > 65535:
        return None
    try:
        link_port = int((link or {}).get("port") or 0)
    except (TypeError, ValueError):
        return None
    if link_port != container_port:
        return None
    return (public_port, container_port)


def _proxy_public_endpoint(link, domain):
    if link is None:
        return None, None
    protocol = (link or {}).get("protocol") or ""
    if protocol not in ("socks5", "mtproto", "http-proxy"):
        return None, None
    if link.get("port_direct_reachable") is True and not _is_single_port_host():
        try:
            return str(domain or ""), int(link.get("port") or 0)
        except (TypeError, ValueError):
            return None, None
    declared = _declared_published_port(link)
    if declared is not None:
        return str(domain or ""), int(declared[0])
    if link.get("tcp_public_domain") and link.get("tcp_public_port"):
        try:
            return str(link.get("tcp_public_domain")), int(link.get("tcp_public_port") or 0)
        except (TypeError, ValueError):
            return None, None
    return None, None


def _proxy_public_port(link):
    _host, _port = _proxy_public_endpoint(link, "")
    return _port


def _proxy_effective_port(protocol, link=None):
    if link is not None:
        _selected_port = _proxy_public_port(link)
        if _selected_port:
            return int(_selected_port)
        try:
            return int(link.get("port") or PROXY_DEFAULT_PORTS.get(protocol, 0))
        except (TypeError, ValueError):
            return int(PROXY_DEFAULT_PORTS.get(protocol, 0))
    if protocol == "socks5":
        return int((TG_PROXY_STATUS.get("socks", {}) or {}).get("port") or SOCKS_PORT or 0)
    if protocol == "mtproto":
        return int((TG_PROXY_STATUS.get("mtproxy", {}) or {}).get("port") or TG_PROXY_PORT or 0)
    if protocol == "http-proxy":
        return int((TG_PROXY_STATUS.get("http", {}) or {}).get("port") or HTTP_PROXY_PORT or 0)
    return 0


def _proxy_effective_host(link, domain):
    _host, _port = _proxy_public_endpoint(link, domain)
    if _host:
        return str(_host)
    return str(domain or "")


def _proxy_mux_bound(port):
    try:
        return int(port) in _PROXY_MUX_PORTS
    except (TypeError, ValueError):
        return False


def _web_bridge_running(port):
    try:
        entry = _WEB_BRIDGE_SERVERS.get(int(port))
    except (TypeError, ValueError):
        return False
    if entry is None:
        return False
    task = entry.get("task")
    return task is not None and not task.done()


def _proxy_liveness_state(protocol, link):
    if link is None:
        return False, "no_inbound", ""
    if not link.get("active"):
        return False, "disabled", ""
    if protocol == "webproxy":
        if tgproxy is None:
            return False, "not_configured", "telegram proxy module is not loaded"
        configure_error = str(WEBPROXY_STATE.get("configure_error") or "")
        if configure_error:
            return False, "not_configured", "WEB proxy is not configured: " + configure_error
        root_err = _webproxy_child_error()
        if root_err:
            return False, "child_dead", "WEB proxy child failed: " + root_err
        if _telemt_web_port_for_uid(_TELEMT_ROOT_CHILD_UID) is None:
            return False, "child_dead", "telemt WEB child is not running for the active WEB inbound"
        status = _telemt_web_status_cached(_TELEMT_ROOT_CHILD_UID)
        if status:
            if status.get("error"):
                return False, "child_dead", str(status.get("error") or "")
            if not status.get("enabled"):
                return False, "child_dead", "telemt WEB child is not running for the active WEB inbound"
            if status.get("healthy") is False:
                return False, "child_dead", "telemt WEB child is not accepting connections"
        elif _TELEMT_ROOT_CHILD_UID not in _TELEMT_PROVISIONED.get("web", set()):
            return False, "child_dead", "telemt WEB child is not running for the active WEB inbound"
        try:
            port = int(link.get("port") or 443)
        except (TypeError, ValueError):
            port = 443
        if port == int(WEBPROXY_PUBLIC_PORT):
            return True, "running", ""
        if _is_single_port_host():
            return False, "disabled", "WEB proxy link port " + str(port) + " is not reachable on this single-port host: only port 443 works here (the bridge rides the panel HTTPS port). Recreate this inbound on port 443 to get a working tg://webproxy link."
        if _web_port_is_fronted(port):
            return False, "disabled", _proxy_disabled_reason("webproxy")
        err = _WEB_BRIDGE_ERRORS.get(port, "")
        if err:
            return False, "listener_failed", "WEB bridge failed on port " + str(port) + ": " + err
        if not _web_bridge_running(port):
            return False, "listener_failed", "WEB bridge is not listening on port " + str(port) + " yet"
        return True, "running", ""
    key = {"socks5": "socks", "mtproto": "mtproxy", "http-proxy": "http"}.get(protocol, "")
    if not key:
        return False, "not_configured", ""
    try:
        port = int(link.get("port") or 0)
    except (TypeError, ValueError):
        port = 0
    if not port:
        return False, "no_port", ""
    entry = TG_PROXY_STATUS.get(key, {}) or {}
    if port not in (entry.get("ports") or []):
        err = _PROXY_MUX_BIND_ERRORS.get(port, "") or str(entry.get("error") or "")
        if err:
            return False, "listener_failed", "Listener failed on port " + str(port) + ": " + err
        return False, "listener_failed", "Listener is not bound on port " + str(port) + " yet"
    if protocol == "mtproto":
        if tgproxy is None:
            return False, "child_dead", "telegram proxy module is not loaded"
        port_fn = _tg_fn("telemt_mtproto_port")
        mt_port = None
        if port_fn is not None:
            try:
                mt_port = port_fn()
            except Exception:
                mt_port = None
        if mt_port is None:
            return False, "child_dead", "telemt MTProto child is not running"
        if str(link.get("uid") or "") not in _TELEMT_PROVISIONED.get("mtproto", set()):
            return False, "child_dead", "MTProto user is not live in the telemt child yet"
    if _is_single_port_host():
        return True, "local_only", ""
    return True, "running", ""


_MTPROTO_GATE_PROBE_TIMEOUT = 2.0


async def _gate_probe_public_tcp(host, port, timeout=_MTPROTO_GATE_PROBE_TIMEOUT):
    started = time.monotonic()
    try:
        _reader, writer = await asyncio.wait_for(asyncio.open_connection(host, port), timeout=timeout)
    except asyncio.TimeoutError:
        return False, "connection timed out after " + str(timeout) + "s (port not published or filtered)", round((time.monotonic() - started) * 1000, 1)
    except OSError as e:
        return False, "connection failed: " + str(e), round((time.monotonic() - started) * 1000, 1)
    except Exception as e:
        return False, "connection failed: " + str(e), round((time.monotonic() - started) * 1000, 1)
    try:
        writer.close()
    except OSError:
        pass
    return True, "", round((time.monotonic() - started) * 1000, 1)



def _proxy_inbound_enabled(link):
    if link is None:
        return False
    protocol = link.get("protocol") or ""
    if protocol not in PROXY_PROTOCOLS:
        return True
    if not link.get("active"):
        return False
    on, _code, _detail = _proxy_liveness_state(protocol, link)
    if not on:
        return False
    if protocol in ("socks5", "mtproto", "http-proxy") and link.get("port_public_reachable") is False:
        return False
    if protocol == "webproxy":
        return True
    if link.get("tcp_public_domain") and link.get("port_public_reachable") is True:
        return True
    if _declared_published_port(link) is not None:
        return True
    if _is_single_port_host():
        return False
    return True


def _proxy_inbound_disabled_reason(link):
    if link is None:
        return ""
    protocol = link.get("protocol") or ""
    if protocol not in PROXY_PROTOCOLS:
        return ""
    if not link.get("active"):
        return "Inbound is disabled"
    if protocol == "webproxy":
        own_err = _webproxy_child_error()
        if own_err:
            return "WEB proxy child failed: " + own_err
        try:
            port = int(link.get("port") or 443)
        except (TypeError, ValueError):
            port = 443
        if port != int(WEBPROXY_PUBLIC_PORT):
            if _web_port_is_fronted(port):
                return _proxy_disabled_reason("webproxy")
            if _is_single_port_host():
                return "WEB proxy link port " + str(port) + " is not reachable on this single-port host: only port 443 works here (the bridge rides the panel HTTPS port). Recreate this inbound on port 443 to get a working tg://webproxy link."
            err = _WEB_BRIDGE_ERRORS.get(port, "")
            if err:
                return "WEB bridge failed on port " + str(port) + ": " + err
            if not _web_bridge_running(port):
                return "WEB bridge is not listening on port " + str(port) + " yet"
        return _proxy_disabled_reason("webproxy")
    if protocol in ("socks5", "mtproto", "http-proxy") and link.get("port_public_reachable") is False:
        if protocol == "mtproto":
            return "MTProto port " + str(link.get("port") or "") + " is not publicly reachable (" + str(link.get("port_check_detail") or "") + "); this inbound works only locally until the port is published (VPS or Railway TCP Proxy)."
        if protocol == "socks5":
            return "SOCKS5 port " + str(link.get("port") or "") + " is not publicly reachable (" + str(link.get("port_check_detail") or "") + "); this inbound works only locally until the port is published (VPS or Railway TCP Proxy). It still works over WebSocket on port 443 (path /ws/" + str(link.get("uid", "")) + ", v2ray or sing-box client with ws+tls)."
        return "HTTP proxy port " + str(link.get("port") or "") + " is not publicly reachable (" + str(link.get("port_check_detail") or "") + "); this inbound works only locally until the port is published (VPS or Railway TCP Proxy). It still works over WebSocket on port 443 (path /ws/" + str(link.get("uid", "")) + ", v2ray or sing-box client with ws+tls)."
    try:
        port = int(link.get("port") or 0)
    except (TypeError, ValueError):
        port = 0
    if not port:
        return "No listener port configured for this inbound; raw TCP listeners cannot be published on a single-port host, use the WEB proxy or a VPS or Railway TCP Proxy"
    err = _PROXY_MUX_BIND_ERRORS.get(port, "")
    if err:
        return "Listener failed to bind port " + str(port) + ": " + err
    if not _proxy_mux_bound(port):
        return "Listener is not bound on port " + str(port) + " yet"
    if _is_single_port_host():
        return "Listener is bound on port " + str(port) + " locally, but this host exposes a single HTTPS port, so raw port " + str(port) + " is not reachable from outside. This inbound still works over WebSocket on port 443 (path /ws/" + str(link.get("uid", "")) + ", v2ray or sing-box client with ws+tls); for Telegram use the WEB proxy instead."
    return _proxy_disabled_reason(protocol, link)


async def _probe_raw_port_public(link, domain):
    protocol = (link or {}).get("protocol") or ""
    if protocol not in ("socks5", "http-proxy", "mtproto"):
        return None, ""
    try:
        port = int(link.get("port") or 0)
    except (TypeError, ValueError):
        port = 0
    if not port:
        link["port_direct_reachable"] = False
        link["public_endpoint_host"] = None
        link["public_endpoint_port"] = None
        return False, "no listener port configured for this inbound"
    direct_ok = False
    direct_detail = ""
    if _is_single_port_host():
        if port == 443:
            direct_detail = "port 443 is owned by the platform TLS edge on a single-port host, the raw multiplexer cannot receive TCP there"
        else:
            direct_detail = "single-port host: no raw TCP port is published, use a declared published port or a TCP proxy"
    else:
        direct_ok, direct_detail, _ms = await _gate_probe_public_tcp(domain, port)
    link["port_direct_reachable"] = bool(direct_ok)
    if direct_ok:
        link["public_endpoint_host"] = str(domain or "")
        link["public_endpoint_port"] = int(port)
        link["port_public_reachable"] = True
        link["port_check_detail"] = ""
        return True, ""
    declared = _declared_published_port(link)
    if declared is not None:
        public_port = int(declared[0])
        ok, detail, _ms = await _gate_probe_public_tcp(domain, public_port)
        link["public_endpoint_host"] = str(domain or "")
        link["public_endpoint_port"] = int(public_port)
        link["port_public_reachable"] = True
        if ok:
            link["port_check_detail"] = ""
            return True, ""
        link["port_check_detail"] = "declared published port " + str(public_port) + " (deployment-declared; self-probe could not verify reachability: " + detail + ")"
        return True, link["port_check_detail"]
    if link.get("tcp_public_domain") and link.get("tcp_public_port"):
        try:
            public_port = int(link.get("tcp_public_port") or 0)
        except (TypeError, ValueError):
            public_port = 0
        if not public_port:
            link["public_endpoint_host"] = None
            link["public_endpoint_port"] = None
            return False, "no public TCP proxy endpoint is stored for this inbound"
        ok, detail, _ms = await _gate_probe_public_tcp(str(link.get("tcp_public_domain")), public_port)
        link["public_endpoint_host"] = str(link.get("tcp_public_domain"))
        link["public_endpoint_port"] = int(public_port)
        link["port_public_reachable"] = bool(ok)
        link["port_check_detail"] = "" if ok else detail
        if ok:
            return True, ""
        return False, "public TCP proxy endpoint " + str(link.get("tcp_public_domain")) + ":" + str(public_port) + " is not reachable (" + detail + ")"
    link["public_endpoint_host"] = None
    link["public_endpoint_port"] = None
    link["port_public_reachable"] = False
    link["port_check_detail"] = "port " + str(port) + " on " + str(domain) + " is not publicly reachable (" + direct_detail + ")"
    return False, "port " + str(port) + " on " + str(domain) + " is not publicly reachable (" + direct_detail + ")"


async def _probe_and_provision_if_needed(link, domain):
    ok, detail = await _probe_raw_port_public(link, domain)
    if ok is not False:
        return ok, detail
    if _declared_published_port(link) is not None:
        return ok, detail
    if (link or {}).get("tcp_public_domain"):
        _stale_uid = str((link or {}).get("uid") or "")
        await _tcp_proxy_release(_stale_uid, "")
        _tcp_proxy_detach(link)
        try:
            await db_execute("DELETE FROM tcp_proxies WHERE uid = ?", "DELETE FROM tcp_proxies WHERE uid = $1", (_stale_uid,))
        except Exception:
            pass
    await _tcp_proxy_provision(link)
    if (link or {}).get("tcp_public_domain"):
        return await _probe_raw_port_public(link, domain)
    return ok, detail


def _proxy_raw_port_unavailable_text(link):
    protocol = (link or {}).get("protocol") or ""
    detail = str((link or {}).get("port_check_detail") or "")
    base = "This inbound needs a published raw TCP port (VPS or Railway TCP Proxy); the raw port is not publicly reachable" + (" (" + detail + ")") + ". "
    if protocol == "mtproto":
        _text = base + "For Telegram use the WEB proxy instead: create a Telegram WEB proxy inbound on port 443, it rides the panel HTTPS port and works on this host. " + "این اینباند به پورت TCP خام منتشرشده نیاز دارد (VPS یا Railway TCP Proxy)؛ پورت خام از بیرون در دسترس نیست. برای تلگرام از پروکسی WEB استفاده کنید."
    else:
        _text = base + "SOCKS5 and HTTP still work over WebSocket on port 443; for Telegram use the WEB proxy instead. " + "این اینباند به پورت TCP خام منتشرشده نیاز دارد (VPS یا Railway TCP Proxy)؛ پورت خام از بیرون در دسترس نیست. SOCKS5 و HTTP روی پورت 443 با WebSocket کار می‌کنند؛ برای تلگرام از پروکسی WEB استفاده کنید."
    if not (link or {}).get("tcp_public_domain") and _declared_published_port(link) is None and (tgproxy is None or tgproxy.tcp_proxy_provider() is None):
        _text = _text + " " + _tcp_proxy_missing_text()
    return _text


def _proxy_inbound_warning(link):
    if link is None:
        return ""
    protocol = link.get("protocol") or ""
    if protocol not in PROXY_PROTOCOLS:
        return ""
    if link.get("port_public_reachable") is False:
        detail = link.get("port_check_detail", "") or ""
        base = "Raw port " + str(link.get("port") or "") + " was checked at creation and is not publicly reachable" + (": " + detail if detail else "") + "."
        if protocol in ("socks5", "http-proxy"):
            _warn = base + " This inbound still works over WebSocket on port 443 (path /ws/" + str(link.get("uid", "")) + ", v2ray or sing-box client with ws+tls); for Telegram use the WEB proxy instead."
        else:
            _warn = base + " Use the WEB proxy instead: create a Telegram WEB proxy inbound on port 443, it rides the panel HTTPS port and works on this host."
        if not link.get("tcp_public_domain") and _declared_published_port(link) is None and (tgproxy is None or tgproxy.tcp_proxy_provider() is None):
            _warn = _warn + " " + _tcp_proxy_missing_text()
        return _warn
    on, _code, _detail = _proxy_liveness_state(protocol, link)
    if on and _code == "local_only" and protocol in ("socks5", "mtproto", "http-proxy"):
        return _proxy_inbound_disabled_reason(link)
    if on:
        return ""
    reason = _detail or _proxy_inbound_disabled_reason(link)
    if protocol in ("socks5", "mtproto", "http-proxy"):
        return reason + " Use the WEB proxy instead: create a Telegram WEB proxy inbound on port 443, it rides the panel HTTPS port and works on this host."
    return reason


def _webproxy_child_error():
    child_errors = WEBPROXY_STATE.get("child_errors") or {}
    return str(child_errors.get(_TELEMT_ROOT_CHILD_UID) or "")


def _proxy_disabled_reason(protocol, link=None):
    if protocol == "webproxy":
        root_err = _webproxy_child_error()
        if root_err:
            return "WEB proxy child failed: " + root_err
        err = (TG_PROXY_STATUS.get("webproxy", {}) or {}).get("error", "") or ""
        if err:
            return "WEB proxy is not configured: " + err
        state_err = WEBPROXY_STATE.get("configure_error", "") or ""
        if state_err:
            return "WEB proxy is not configured: " + state_err
        return "WEB proxy is not configured (secret_key missing)"
    if protocol in ("socks5", "mtproto", "http-proxy"):
        key = {"socks5": "socks", "mtproto": "mtproxy", "http-proxy": "http"}.get(protocol, "")
        port = {"socks5": SOCKS_PORT, "mtproto": TG_PROXY_PORT, "http-proxy": HTTP_PROXY_PORT}.get(protocol, 0)
        if link is not None:
            try:
                port = int(link.get("port") or 0) or port
            except (TypeError, ValueError):
                pass
        err = (TG_PROXY_STATUS.get(key, {}) or {}).get("error", "") or ""
        if not port:
            return "No listener port configured on this host (port 0); raw TCP listeners cannot be published on a single-port host, use the WEB proxy or a VPS or Railway TCP Proxy"
        if err:
            return "Listener failed on port " + str(port) + ": " + err
        if _proxy_mux_bound(port):
            return "Listener is bound on port " + str(port) + " locally and accepting connections, but the public address is not reachable from outside on this host (single HTTPS port only, or the TCP port is closed)"
        return "Listener is not bound on port " + str(port) + " yet"
    return ""


async def _listener_cards(public_port, request=None):
    port = str(public_port or "")
    await refresh_proxy_listener_status()
    try:
        await _telemt_refresh_web_status()
    except Exception:
        pass
    cards = [
        {"id": "vless", "name": "VLESS", "protocol": "vless-ws", "port": port, "enabled": True, "reason": "", "reason_code": "running_panel"},
        {"id": "vmess", "name": "VMess", "protocol": "vmess-ws", "port": port, "enabled": True, "reason": "", "reason_code": "running_panel"},
        {"id": "trojan", "name": "Trojan", "protocol": "trojan-ws", "port": port, "enabled": True, "reason": "", "reason_code": "running_panel"},
        {"id": "shadowsocks", "name": "Shadowsocks", "protocol": "ss-ws", "port": port, "enabled": True, "reason": "", "reason_code": "running_panel"},
    ]
    async with LINKS_LOCK:
        rows = list(LINKS.values())
    for _pid, _pname, _pport in (("socks5", "SOCKS5", SOCKS_PORT), ("mtproto", "MTProto", TG_PROXY_PORT), ("http-proxy", "HTTP proxy", HTTP_PROXY_PORT)):
        _card_link = None
        for _row in rows:
            if (_row.get("protocol") or "") == _pid and _row.get("active"):
                _card_link = _row
                break
        if _card_link is None:
            for _row in rows:
                if (_row.get("protocol") or "") == _pid:
                    _card_link = _row
                    break
        _on, _code, _detail = _proxy_liveness_state(_pid, _card_link)
        _shown_port = _pport
        if _card_link is not None:
            try:
                _shown_port = int(_card_link.get("port") or _pport or 0)
            except (TypeError, ValueError):
                _shown_port = _pport
        if _on:
            _why = ""
            if _code == "local_only":
                _why = "Listener is bound on port " + str(_shown_port) + " and accepting connections locally, but the public address is not reachable from outside on this host (single HTTPS port only, or the TCP port is closed), so a remote client cannot use this port"
        else:
            _why = _detail or (_proxy_inbound_disabled_reason(_card_link) if _card_link is not None else _proxy_disabled_reason(_pid))
        cards.append({"id": _pid, "name": _pname, "protocol": _pid, "port": str(_shown_port) if _shown_port else "—", "enabled": bool(_on), "reason": _why, "reason_code": _code})
    _web_link = None
    for _row in rows:
        if (_row.get("protocol") or "") == "webproxy" and _row.get("active"):
            _web_link = _row
            break
    if _web_link is None:
        for _row in rows:
            if (_row.get("protocol") or "") == "webproxy":
                _web_link = _row
                break
    _web_on, _web_code, _web_detail = _proxy_liveness_state("webproxy", _web_link)
    cards.append({"id": "webproxy", "name": "WEB proxy", "protocol": "webproxy", "port": str(WEBPROXY_PUBLIC_PORT), "enabled": bool(_web_on), "reason": "" if _web_on else (_web_detail or _proxy_disabled_reason("webproxy")), "reason_code": "running_panel" if _web_on else _web_code, "shared": _webproxy_shared_443(), "tg_web_secret": _WEB_BASE_SECRET_HEX or "", "tg_web_secret_source": _WEB_BASE_SECRET_SOURCE or ""})
    return cards


PROXY_LISTENER_PROBE_TTL = 30.0
_PROXY_LISTENER_PROBE_AT = 0.0
_PROXY_LISTENER_PROBE_LOCK = asyncio.Lock()


async def _probe_raw_listener(port, protocol):
    try:
        reader, writer = await asyncio.wait_for(asyncio.open_connection("127.0.0.1", port), timeout=1.0)
    except (asyncio.TimeoutError, OSError):
        return False, "listener not reachable on 127.0.0.1:" + str(port)
    try:
        if protocol == "socks5":
            writer.write(b"\x05\x01\x02")
            await writer.drain()
            resp = await asyncio.wait_for(reader.readexactly(2), timeout=1.0)
            if resp == b"\x05\x02":
                return True, ""
            return False, "listener on 127.0.0.1:" + str(port) + " rejected the SOCKS5 greeting"
        if protocol == "mtproto":
            return True, ""
        try:
            writer.write(b"CONNECT 127.0.0.1:9 HTTP/1.1\r\nHost: 127.0.0.1:9\r\n\r\n")
            await writer.drain()
            resp = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout=1.0)
        except (asyncio.TimeoutError, asyncio.IncompleteReadError, asyncio.LimitOverrunError, ConnectionError, OSError):
            return False, "listener on 127.0.0.1:" + str(port) + " did not answer the HTTP proxy probe, the multiplexer accepts TCP but the HTTP handler does not respond"
        if resp.startswith(b"HTTP/1.1 407"):
            return True, ""
        return False, "listener on 127.0.0.1:" + str(port) + " did not answer the HTTP proxy probe with 407, got: " + resp.decode("iso-8859-1", "ignore").split("\r\n")[0]
    except (asyncio.TimeoutError, OSError):
        return False, "listener on 127.0.0.1:" + str(port) + " did not answer the probe"
    finally:
        try:
            writer.close()
        except OSError:
            pass


def _safe_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


async def refresh_proxy_listener_status(force=False):
    global _PROXY_LISTENER_PROBE_AT
    now = time.monotonic()
    if not force and now - _PROXY_LISTENER_PROBE_AT < PROXY_LISTENER_PROBE_TTL:
        return TG_PROXY_STATUS
    async with _PROXY_LISTENER_PROBE_LOCK:
        now = time.monotonic()
        if not force and now - _PROXY_LISTENER_PROBE_AT < PROXY_LISTENER_PROBE_TTL:
            return TG_PROXY_STATUS
        async with LINKS_LOCK:
            _status_rows = list(LINKS.values())
        _mux_ports_by_key = {}
        for key, protocol, env_port in (("socks", "socks5", SOCKS_PORT), ("mtproxy", "mtproto", TG_PROXY_PORT), ("http", "http-proxy", HTTP_PROXY_PORT)):
            _ports = set()
            if env_port:
                _env_port = _safe_int(env_port, 0)
                if _env_port:
                    _ports.add(_env_port)
            for _l in _status_rows:
                if (_l.get("protocol") or "") == protocol and _l.get("active"):
                    try:
                        _p = int(_l.get("port") or 0)
                    except (TypeError, ValueError):
                        _p = 0
                    if _p:
                        _ports.add(_p)
            _mux_ports_by_key[key] = sorted(_ports)
        _probe_by_key = {}
        _probe_targets = []
        for _key, _proto in (("socks", "socks5"), ("mtproxy", "mtproto"), ("http", "http-proxy")):
            for _port in _mux_ports_by_key.get(_key, []):
                _probe_targets.append((_key, _port, _proto))
        if _probe_targets:
            probed = await asyncio.gather(*[_probe_raw_listener(_port, _proto) for _key, _port, _proto in _probe_targets], return_exceptions=True)
            for (_key, port, _proto), ok in zip(_probe_targets, probed):
                if isinstance(ok, Exception):
                    _probe_by_key[(_key, port)] = (False, "listener probe failed on 127.0.0.1:" + str(port))
                else:
                    _probe_by_key[(_key, port)] = (ok[0], ok[1])
            for port in sorted({p for _key, p, _proto in _probe_targets}):
                _port_results = [_probe_by_key.get((_key, port), (False, "")) for _key in ("socks", "mtproxy", "http")]
                if any(r[0] for r in _port_results):
                    _PROXY_MUX_PORTS.add(port)
                    _PROXY_MUX_BIND_ERRORS.pop(port, None)
                elif port in _PROXY_MUX_PORTS:
                    _PROXY_MUX_PORTS.discard(port)
                    _first_fail = next((r[1] for r in _port_results if r[1]), "listener probe failed on 127.0.0.1:" + str(port))
                    _PROXY_MUX_BIND_ERRORS[port] = _first_fail
        verified_at = datetime.now(UTC).isoformat()
        for key in ("socks", "mtproxy", "http"):
            entry = TG_PROXY_STATUS.get(key, {})
            ports = _mux_ports_by_key.get(key, [])
            live_ports = [p for p in ports if _probe_by_key.get((key, p), (False, ""))[0]]
            failed_ports = {str(p): _probe_by_key[(key, p)][1] for p in ports if (key, p) in _probe_by_key and not _probe_by_key[(key, p)][0]}
            if not ports:
                entry["enabled"] = False
                entry["port"] = 0
                entry["error"] = ""
                entry["ports"] = []
                entry["failed_ports"] = {}
            elif PROXY_START_ERRORS.get(key):
                entry["enabled"] = False
                entry["port"] = _safe_int(ports[0], 0)
                entry["error"] = PROXY_START_ERRORS[key]
                entry["ports"] = live_ports
                entry["failed_ports"] = failed_ports
            else:
                entry["enabled"] = bool(live_ports)
                entry["port"] = _safe_int(live_ports[0], 0) if live_ports else _safe_int(ports[0], 0)
                entry["error"] = "" if live_ports else "; ".join(str(p) + ": " + str(e) for p, e in failed_ports.items())
                entry["ports"] = live_ports
                entry["failed_ports"] = failed_ports
            entry["verified_at"] = verified_at
            TG_PROXY_STATUS[key] = entry
        _web_bridge_ports = sorted({_safe_int(_l.get("port") or 443, 443) for _l in _status_rows if (_l.get("protocol") or "") == "webproxy" and _l.get("active") and _safe_int(_l.get("port") or 443, 443) != int(WEBPROXY_PUBLIC_PORT)})
        for _bp in _web_bridge_ports:
            _alive, _berr = await _probe_raw_listener(_bp, "http-proxy")
            if _alive:
                _WEB_BRIDGE_ERRORS.pop(_bp, None)
            elif _bp not in _WEB_BRIDGE_ERRORS:
                _WEB_BRIDGE_ERRORS[_bp] = _berr
        web_entry = TG_PROXY_STATUS.get("webproxy", {})
        health = None
        try:
            health = await _tg_call("telemt_health")
        except Exception:
            health = None
        if isinstance(health, dict):
            TELEMT_HEALTH["available"] = bool(health.get("available"))
            TELEMT_HEALTH["mtproto"] = bool((health.get("mtproto") or {}).get("healthy"))
            TELEMT_HEALTH["mtproto_users_live"] = int((health.get("mtproto") or {}).get("users_live") or 0)
            TELEMT_HEALTH["mtproto_users_total"] = int((health.get("mtproto") or {}).get("users_total") or 0)
            _web_children = health.get("web") or {}
            if isinstance(_web_children, dict):
                TELEMT_HEALTH["web"] = any(bool((child or {}).get("healthy")) for child in _web_children.values())
                TELEMT_HEALTH["web_children_live"] = sum(1 for child in _web_children.values() if bool((child or {}).get("healthy")))
                TELEMT_HEALTH["web_children_total"] = len(_web_children)
            else:
                TELEMT_HEALTH["web"] = False
                TELEMT_HEALTH["web_children_live"] = 0
                TELEMT_HEALTH["web_children_total"] = 0
            TELEMT_HEALTH["error"] = str(health.get("error") or "")
        web_entry["port"] = WEBPROXY_PUBLIC_PORT
        web_entry["ports"] = [WEBPROXY_PUBLIC_PORT] + sorted({_safe_int(_l.get("port") or 443, 443) for _l in _status_rows if (_l.get("protocol") or "") == "webproxy" and _l.get("active") and _safe_int(_l.get("port") or 443, 443) != int(WEBPROXY_PUBLIC_PORT) and _web_bridge_running(_safe_int(_l.get("port") or 443, 443))})
        web_entry["failed_ports"] = {str(p): e for p, e in _WEB_BRIDGE_ERRORS.items()}
        web_entry["bridge_ports"] = sorted({_safe_int(_l.get("port") or 443, 443) for _l in _status_rows if (_l.get("protocol") or "") == "webproxy" and _l.get("active") and _safe_int(_l.get("port") or 443, 443) != int(WEBPROXY_PUBLIC_PORT) and _web_bridge_running(_safe_int(_l.get("port") or 443, 443))})
        web_entry["bridge_errors"] = dict(_WEB_BRIDGE_ERRORS)
        try:
            await _ensure_web_base_secret()
        except Exception:
            pass
        if _WEB_BASE_SECRET_HEX:
            WEBPROXY_STATE["configure_error"] = ""
        if WEBPROXY_STATE.get("configure_error"):
            web_entry["enabled"] = False
            web_entry["error"] = str(WEBPROXY_STATE["configure_error"])
        elif not TELEMT_HEALTH.get("available"):
            web_entry["enabled"] = False
            web_entry["error"] = "telemt binary is not available on this host (Telegram proxies need telemt)"
        else:
            web_entry["enabled"] = True
            web_entry["error"] = ""
        web_entry["verified_at"] = verified_at
        TG_PROXY_STATUS["webproxy"] = web_entry
        try:
            await _telemt_refresh_web_status()
        except Exception:
            pass
        child_errors = WEBPROXY_STATE.get("child_errors") or {}
        root_err = str(child_errors.get(_TELEMT_ROOT_CHILD_UID) or "")
        web_entry["root_error"] = root_err
        web_entry["root_child"] = {"running": _telemt_web_port_for_uid(_TELEMT_ROOT_CHILD_UID) is not None, "error": root_err}
        if web_entry.get("enabled"):
            async with LINKS_LOCK:
                web_rows = [link for link in LINKS.values() if (link.get("protocol") or "") == "webproxy" and link.get("active")]
            if web_rows:
                status = _telemt_web_status_cached(_TELEMT_ROOT_CHILD_UID)
                if not (status.get("enabled") and not status.get("error")):
                    web_entry["enabled"] = False
                    if root_err:
                        web_entry["error"] = "telemt WEB child is not running for the active WEB inbound: " + root_err
                    else:
                        web_entry["error"] = "telemt WEB child is not running for the active WEB inbound"
                    TG_PROXY_STATUS["webproxy"] = web_entry
        _PROXY_LISTENER_PROBE_AT = time.monotonic()
        return TG_PROXY_STATUS


async def _telemt_retry_web_children():
    if tgproxy is None:
        return
    if get_domain() == "localhost":
        return
    async with LINKS_LOCK:
        rows = [link for link in LINKS.values() if (link.get("protocol") or "") == "webproxy" and link.get("active")]
    if not rows:
        return
    child_errors = WEBPROXY_STATE.get("child_errors") or {}
    needs = _TELEMT_ROOT_CHILD_UID not in _TELEMT_PROVISIONED.get("web", set()) or _TELEMT_ROOT_CHILD_UID in child_errors or _telemt_web_port_for_uid(_TELEMT_ROOT_CHILD_UID) is None
    if not needs:
        return
    try:
        await _telemt_sync_root_vhost()
    except Exception:
        pass


async def _proxy_mux_ensure_ports(ports):
    wanted = []
    for _p in ports or []:
        try:
            _v = int(_p)
        except (TypeError, ValueError):
            continue
        if _v and _v not in wanted:
            wanted.append(_v)
    if not wanted:
        return {"bound": [], "failed": {}}
    for _p in wanted:
        if _web_bridge_running(_p):
            await _release_web_bridge_port(_p)
    if tgproxy is None:
        for _p in wanted:
            if _p not in _PROXY_MUX_PORTS:
                _PROXY_MUX_BIND_ERRORS[_p] = "telegram proxy multiplexer is not available in this telegram module build"
        return {"bound": [], "failed": {str(p): _PROXY_MUX_BIND_ERRORS[p] for p in wanted if p in _PROXY_MUX_BIND_ERRORS}}
    ensure = _tg_fn("ensure_proxy_ports")
    if ensure is None:
        for _p in wanted:
            if _p not in _PROXY_MUX_PORTS:
                _PROXY_MUX_BIND_ERRORS[_p] = "telegram proxy multiplexer is not available in this telegram module build"
        return {"bound": [], "failed": {str(p): _PROXY_MUX_BIND_ERRORS[p] for p in wanted if p in _PROXY_MUX_BIND_ERRORS}}
    try:
        result = ensure(wanted)
        if inspect.isawaitable(result):
            result = await result
    except Exception as exc:
        for _p in wanted:
            if _p not in _PROXY_MUX_PORTS:
                _PROXY_MUX_BIND_ERRORS[_p] = str(exc)
        return {"bound": [], "failed": {str(p): _PROXY_MUX_BIND_ERRORS[p] for p in wanted if p in _PROXY_MUX_BIND_ERRORS}}
    if isinstance(result, dict):
        for _p in result.get("bound") or []:
            try:
                _PROXY_MUX_PORTS.add(int(_p))
                _PROXY_MUX_BIND_ERRORS.pop(int(_p), None)
            except (TypeError, ValueError):
                pass
        for _k, _v in (result.get("failed") or {}).items():
            try:
                _PROXY_MUX_BIND_ERRORS[int(_k)] = str(_v)
            except (TypeError, ValueError):
                pass
        for _p in result.get("ports") or []:
            try:
                _PROXY_MUX_PORTS.add(int(_p))
                _PROXY_MUX_BIND_ERRORS.pop(int(_p), None)
            except (TypeError, ValueError):
                pass
    return result if isinstance(result, dict) else {"bound": [], "failed": {}}


async def _ensure_web_bridge_port(port):
    try:
        port = int(port or 0)
    except (TypeError, ValueError):
        return False
    if not port or port == int(WEBPROXY_PUBLIC_PORT):
        return True
    if _web_port_is_fronted(port):
        _WEB_BRIDGE_ERRORS.pop(port, None)
        return True
    if _web_bridge_running(port):
        return True
    if _is_single_port_host():
        _WEB_BRIDGE_ERRORS[port] = "WEB bridge port " + str(port) + " cannot work on this host: only port 443 is reachable on a single-port host (the WEB bridge rides the panel HTTPS port)"
        return False
    if port == int(CONFIG.get("port", 8000) or 0):
        _WEB_BRIDGE_ERRORS[port] = "WEB bridge port " + str(port) + " is the panel port, it cannot listen on its own port as well"
        return False
    probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        probe.bind(("0.0.0.0", port))
    except OSError as exc:
        _WEB_BRIDGE_ERRORS[port] = "WEB bridge could not bind port " + str(port) + ": " + str(exc)
        return False
    finally:
        try:
            probe.close()
        except OSError:
            pass
    config = uvicorn.Config(app, host="0.0.0.0", port=port, log_level="error", lifespan="off")
    server = uvicorn.Server(config)
    task = asyncio.create_task(server.serve())
    _WEB_BRIDGE_SERVERS[port] = {"server": server, "task": task}
    deadline = time.monotonic() + 5.0
    while time.monotonic() < deadline:
        if task.done():
            _WEB_BRIDGE_ERRORS[port] = "WEB bridge server on port " + str(port) + " stopped while starting"
            _WEB_BRIDGE_SERVERS.pop(port, None)
            return False
        try:
            reader, writer = await asyncio.wait_for(asyncio.open_connection("127.0.0.1", port), timeout=0.5)
            writer.close()
            _WEB_BRIDGE_ERRORS.pop(port, None)
            return True
        except (asyncio.TimeoutError, OSError):
            await asyncio.sleep(0.2)
    if task.done():
        _WEB_BRIDGE_ERRORS[port] = "WEB bridge server on port " + str(port) + " stopped while starting"
        _WEB_BRIDGE_SERVERS.pop(port, None)
        return False
    _WEB_BRIDGE_ERRORS.pop(port, None)
    return True


async def _release_web_bridge_port(port):
    try:
        port = int(port or 0)
    except (TypeError, ValueError):
        return
    entry = _WEB_BRIDGE_SERVERS.pop(port, None)
    if entry is None:
        return
    server = entry.get("server")
    task = entry.get("task")
    try:
        server.should_exit = True
    except Exception:
        pass
    if task is not None:
        try:
            await asyncio.wait_for(task, timeout=5.0)
        except (asyncio.TimeoutError, Exception):
            task.cancel()
    _WEB_BRIDGE_ERRORS.pop(port, None)


async def _release_web_bridge_port_if_unused(port):
    try:
        port = int(port or 0)
    except (TypeError, ValueError):
        return
    if not port or port == int(WEBPROXY_PUBLIC_PORT):
        return
    for _l in list(LINKS.values()):
        if (_l.get("protocol") or "") == "webproxy" and _l.get("active"):
            try:
                if int(_l.get("port") or 443) == port and not _web_port_is_fronted(port):
                    return
            except (TypeError, ValueError):
                continue
    await _release_web_bridge_port(port)


async def _proxy_ensure_inbound_ports(link):
    if link is None:
        return
    protocol = link.get("protocol") or ""
    if protocol not in PROXY_PROTOCOLS:
        return
    if not link.get("active"):
        return
    try:
        port = int(link.get("port") or 0)
    except (TypeError, ValueError):
        port = 0
    if protocol == "webproxy":
        if port and port != int(WEBPROXY_PUBLIC_PORT):
            await _ensure_web_bridge_port(port)
        return
    if port:
        await _proxy_mux_ensure_ports([port])


async def _proxy_ensure_active_proxy_ports():
    mux_ports = []
    for _l in list(LINKS.values()):
        if (_l.get("protocol") or "") in ("socks5", "mtproto", "http-proxy") and _l.get("active"):
            try:
                _p = int(_l.get("port") or 0)
            except (TypeError, ValueError):
                _p = 0
            if _p and _p not in mux_ports:
                mux_ports.append(_p)
    if mux_ports:
        await _proxy_mux_ensure_ports(mux_ports)
    for _l in list(LINKS.values()):
        if (_l.get("protocol") or "") == "webproxy" and _l.get("active"):
            try:
                _p = int(_l.get("port") or 443)
            except (TypeError, ValueError):
                _p = 443
            if _p != int(WEBPROXY_PUBLIC_PORT):
                if _web_port_is_fronted(_p):
                    if _web_bridge_running(_p):
                        await _release_web_bridge_port(_p)
                else:
                    await _ensure_web_bridge_port(_p)


async def _proxy_listener_refresh_loop():
    while True:
        await asyncio.sleep(PROXY_LISTENER_PROBE_TTL)
        try:
            await _proxy_ensure_active_proxy_ports()
        except Exception:
            pass
        try:
            await refresh_proxy_listener_status(force=True)
        except Exception:
            pass
        try:
            await _telemt_retry_web_children()
        except Exception:
            pass


async def _telemt_mtproto_sync_loop():
    while True:
        await asyncio.sleep(15.0)
        try:
            await _telemt_mtproto_sync_once()
        except Exception:
            pass


async def _telemt_mtproto_sync_once():
    global _TELEMT_MTPROTO_GENERATION
    if tgproxy is None:
        return
    gen_fn = _tg_fn("telemt_mtproto_generation")
    gen = 0
    if gen_fn is not None:
        try:
            gen = int(gen_fn() or 0)
        except Exception:
            gen = 0
    restarted = gen != _TELEMT_MTPROTO_GENERATION and _TELEMT_MTPROTO_GENERATION != 0
    _TELEMT_MTPROTO_GENERATION = gen
    async with LINKS_LOCK:
        rows = [link for link in LINKS.values() if (link.get("protocol") or "") == "mtproto" and link.get("active")]
    for link in rows:
        uid = str(link.get("uid", ""))
        if restarted:
            _TELEMT_MTPROTO_STATS.pop(uid, None)
        try:
            stats = await _tg_call("telemt_mtproto_user_stats", uid)
        except Exception:
            stats = None
        if not isinstance(stats, dict) or not stats:
            try:
                await _telemt_provision_mtproto(link)
            except Exception:
                pass
            continue
        try:
            total = int(stats.get("total_octets") or 0)
            current_connections = int(stats.get("current_connections") or 0)
            active_unique_ips = int(stats.get("active_unique_ips") or 0)
        except (TypeError, ValueError):
            continue
        counted_fn = _tg_fn("mtproto_counted_bytes")
        counted = 0
        if counted_fn is not None:
            try:
                counted = int(counted_fn(uid) or 0)
            except Exception:
                counted = 0
        base = _TELEMT_MTPROTO_STATS.get(uid)
        if base is None:
            _TELEMT_MTPROTO_STATS[uid] = {"telemt": total, "counted": counted, "current_connections": current_connections, "active_unique_ips": active_unique_ips}
            continue
        if total < base["telemt"]:
            base["telemt"] = total
            base["counted"] = counted
            base["current_connections"] = current_connections
            base["active_unique_ips"] = active_unique_ips
            continue
        residual = (total - base["telemt"]) - (counted - base["counted"])
        base["telemt"] = total
        base["counted"] = counted
        base["current_connections"] = current_connections
        base["active_unique_ips"] = active_unique_ips
        if residual > 0:
            try:
                await consume_quota_partial(uid, residual)
            except Exception:
                pass
    try:
        _tls_primary, _tls_extras = _telemt_mtproto_tls_wanted(rows)
        _current_tls = await _tg_call("telemt_mtproto_tls")
        if isinstance(_current_tls, (list, tuple)) and len(_current_tls) == 2:
            _cur_primary = str(_current_tls[0] or "")
            _cur_extras = sorted(str(item) for item in (_current_tls[1] or []))
            if _cur_primary != _tls_primary or _cur_extras != sorted(_tls_extras):
                await _tg_call("telemt_mtproto_set_tls", _tls_primary, _tls_extras)
    except Exception:
        pass
    try:
        _links_host, _links_port = _telemt_mtproto_links_wanted(rows)
        _current_links = await _tg_call("telemt_mtproto_links")
        if isinstance(_current_links, (list, tuple)) and len(_current_links) == 2:
            _cur_host = str(_current_links[0] or "").strip() or None
            try:
                _cur_port = int(_current_links[1]) if _current_links[1] is not None else None
            except (TypeError, ValueError):
                _cur_port = None
            if _cur_host != _links_host or _cur_port != _links_port:
                await _tg_call("telemt_mtproto_set_links", _links_host, _links_port)
    except Exception:
        pass


async def _telemt_web_sync_loop():
    while True:
        await asyncio.sleep(15.0)
        try:
            await _telemt_web_sync_once()
        except Exception:
            pass


async def _telemt_web_sync_once():
    global _TELEMT_WEB_GENERATION
    if tgproxy is None:
        return
    gen_fn = _tg_fn("telemt_web_generation")
    gen = 0
    if gen_fn is not None:
        try:
            gen = int(gen_fn() or 0)
        except Exception:
            gen = 0
    restarted = gen != _TELEMT_WEB_GENERATION and _TELEMT_WEB_GENERATION != 0
    _TELEMT_WEB_GENERATION = gen
    async with LINKS_LOCK:
        rows = [link for link in LINKS.values() if (link.get("protocol") or "") == "webproxy" and link.get("active")]
    runtime_up = 0
    runtime_down = 0
    runtime_ok = False
    try:
        status = await _tg_call("telemt_web_status", _TELEMT_ROOT_CHILD_UID)
        if isinstance(status, dict) and status.get("enabled"):
            runtime_up = int(status.get("runtime_bytes_up") or 0)
            runtime_down = int(status.get("runtime_bytes_down") or 0)
            runtime_ok = True
    except Exception:
        runtime_ok = False
    now = time.monotonic()
    prev_runtime = _TELEMT_WEB_RUNTIME_LAST.get("sample")
    runtime_delta = 0
    runtime_up_bps = 0
    runtime_down_bps = 0
    if prev_runtime is not None and runtime_ok:
        dt = max(now - prev_runtime[0], 0.001)
        runtime_delta = max(0, runtime_up - prev_runtime[1]) + max(0, runtime_down - prev_runtime[2])
        runtime_up_bps = max(0, int((runtime_up - prev_runtime[1]) / dt))
        runtime_down_bps = max(0, int((runtime_down - prev_runtime[2]) / dt))
    if runtime_ok:
        _TELEMT_WEB_RUNTIME_LAST["sample"] = (now, runtime_up, runtime_down)
    total_moved = 0
    fresh = False
    for link in rows:
        uid = str(link.get("uid", ""))
        if restarted:
            _TELEMT_WEB_STATS.pop(uid, None)
        try:
            stats = await _tg_call("telemt_web_user_stats", uid)
        except Exception:
            stats = None
        if not isinstance(stats, dict) or not stats:
            continue
        try:
            total = int(stats.get("total_octets") or 0)
            current_connections = int(stats.get("current_connections") or 0)
            active_unique_ips = int(stats.get("active_unique_ips") or 0)
        except (TypeError, ValueError):
            continue
        counted = int(_WEB_TOKEN_CHARGED.get(uid) or 0)
        base = _TELEMT_WEB_STATS.get(uid)
        if base is None:
            _TELEMT_WEB_STATS[uid] = {"telemt": total, "counted": counted, "current_connections": current_connections, "active_unique_ips": active_unique_ips, "total_bps": 0, "last_sync": now}
            fresh = True
            continue
        if total < base["telemt"]:
            base["telemt"] = total
            base["counted"] = counted
            base["current_connections"] = current_connections
            base["active_unique_ips"] = active_unique_ips
            base["total_bps"] = 0
            base["last_sync"] = now
            continue
        delta_telemt = total - base["telemt"]
        total_moved += max(0, delta_telemt)
        residual = delta_telemt - (counted - base["counted"])
        dt_sync = max(now - float(base.get("last_sync") or now), 0.001)
        base["telemt"] = total
        base["counted"] = counted
        base["current_connections"] = current_connections
        base["active_unique_ips"] = active_unique_ips
        base["total_bps"] = max(0, int(delta_telemt / dt_sync)) if delta_telemt > 0 else 0
        base["last_sync"] = now
        if residual > 0:
            try:
                await consume_quota_partial(uid, residual)
            except Exception:
                pass
    window_fallback = bool(runtime_ok and runtime_delta > 0 and total_moved == 0 and rows and not fresh)
    if window_fallback:
        _TELEMT_WEB_FALLBACK["streak"] = int(_TELEMT_WEB_FALLBACK.get("streak") or 0) + 1
    else:
        _TELEMT_WEB_FALLBACK["streak"] = 0
    active_now = _TELEMT_WEB_FALLBACK["streak"] >= 2
    if active_now and not _TELEMT_WEB_FALLBACK.get("active"):
        _TELEMT_WEB_FALLBACK["since"] = datetime.now(UTC).isoformat()
    _TELEMT_WEB_FALLBACK["active"] = active_now
    _TELEMT_WEB_FALLBACK["runtime_up"] = runtime_up
    _TELEMT_WEB_FALLBACK["runtime_down"] = runtime_down
    _TELEMT_WEB_FALLBACK["runtime_up_bps"] = runtime_up_bps
    _TELEMT_WEB_FALLBACK["runtime_down_bps"] = runtime_down_bps


def proxy_link_for_uid(uid, protocol, host, port, variant="dd", domain="www.google.com", token=""):
    stored = LINKS.get(uid) or {"uid": uid}
    try:
        use_port = int(port or stored.get("port") or 0)
    except (TypeError, ValueError):
        use_port = 0
    if protocol in PROXY_PROTOCOLS:
        merged = dict(stored)
        merged["port"] = use_port
        if protocol == "webproxy":
            if not stored.get("active"):
                return ""
        elif not _proxy_inbound_enabled(merged):
            return ""
    if protocol in ("socks5", "mtproto", "http-proxy"):
        _pub_host, _pub_port = _proxy_public_endpoint(stored, host)
        if _pub_host and _pub_port:
            host = str(_pub_host)
            use_port = int(_pub_port)
    if protocol == "socks5":
        user, pw = _proxy_creds_for_link(stored)
        return tgproxy.socks5_link(host, use_port, user, pw) if tgproxy is not None else ""
    if protocol == "http-proxy":
        user, pw = _proxy_creds_for_link(stored)
        return tgproxy.http_proxy_link(host, use_port, user, pw) if tgproxy is not None else ""
    if protocol == "mtproto":
        if tgproxy is None:
            return ""
        return tgproxy.mtproxy_link_for_uid(host, use_port, uid, variant, domain)
    if protocol == "webproxy":
        token = str(token or "").strip().lower()
        if not token:
            return ""
        try:
            return _web_link(host, token, merged, use_port)
        except ValueError:
            return ""
    return ""


def _v2ray_ws_proxy_config(link, domain, username, password):
    protocol = link.get("protocol", "")
    outbound_protocol = "socks" if protocol == "socks5" else "http"
    return {"protocol": outbound_protocol, "settings": {"servers": [{"address": str(domain), "port": 443, "users": [{"user": str(username), "pass": str(password)}]}]}, "streamSettings": {"network": "ws", "security": "tls", "tlsSettings": {"serverName": str(domain)}, "wsSettings": {"path": "/ws/" + str(link.get("uid", "")), "headers": {"Host": str(domain)}}}}


def proxy_links_for_link(link, host):
    uid = link.get("uid", "")
    protocol = link.get("protocol", "")
    variant = link.get("mtproto_variant", "dd") or "dd"
    domain = link.get("mtproto_domain", "www.google.com") or "www.google.com"
    port = int(link.get("port") or 443)
    token = str(link.get("webproxy_token") or "").strip().lower()
    _tcp_host = host
    _tcp_port = port
    _pub_host, _pub_port = _proxy_public_endpoint(link, host)
    if _pub_host and _pub_port:
        _tcp_host = str(_pub_host)
        _tcp_port = int(_pub_port)
    _link_enabled = _proxy_inbound_enabled(link) if protocol in PROXY_PROTOCOLS else True
    out = {"protocol_link": proxy_link_for_uid(uid, protocol, host, port, variant, domain, token), "enabled": _link_enabled, "reason": "" if _link_enabled else _proxy_inbound_disabled_reason(link)}
    if protocol in ("socks5", "mtproto", "http-proxy"):
        out["raw_port_available"] = None if link.get("port_public_reachable") is None else bool(link.get("port_public_reachable"))
        out["raw_port_note"] = _proxy_raw_port_unavailable_text(link) if link.get("port_public_reachable") is False else ""
        _tcp_status = _tcp_proxy_status(link)
        if _tcp_status is not None:
            out["tcp_proxy"] = _tcp_status
    if protocol == "mtproto" and tgproxy is not None:
        if not _link_enabled:
            out["variants"] = {}
        else:
            out["variants"] = tgproxy.mtproxy_links_for_uid(_tcp_host, _tcp_port, uid, domain)
        out["variant"] = variant
    if protocol == "webproxy":
        if token and link.get("active"):
            try:
                out["all_ports"] = [{"port": port, "token": token, "secret": _web_link_secret_for_link(link, port), "link": _web_link(host, token, link, port), "link_https": _web_link_https(host, token, link, port)}]
            except ValueError:
                out["all_ports"] = []
        else:
            out["all_ports"] = []
    if protocol in ("socks5", "http-proxy"):
        user, pw = _proxy_creds_for_link(link)
        out["username"] = user
        out["password"] = pw
        out["port"] = _tcp_port
        out["ws_path"] = "/ws/" + str(uid)
        out["ws_enabled"] = bool(link.get("active"))
        out["v2ray_ws"] = _v2ray_ws_proxy_config(link, host, user, pw)
    if link.get("port_public_reachable") is not None:
        out["port_public_reachable"] = bool(link.get("port_public_reachable"))
        out["port_check_detail"] = link.get("port_check_detail", "") or ""
    if protocol == "webproxy":
        out["port"] = port
        out["webproxy_token"] = token
        if token and link.get("active"):
            try:
                out["secret"] = _web_link_secret_for_link(link, port)
                out["link_https"] = _web_link_https(host, token, link, port)
            except ValueError:
                out["secret"] = ""
                out["link_https"] = ""
        else:
            out["secret"] = ""
            out["link_https"] = ""
    return out


def _link_proxy_view(link, host):
    if (link.get("protocol") or "") not in PROXY_PROTOCOLS:
        return None
    return proxy_links_for_link(link, host)

def _safe_protocol_link(uid, remark="SulgX", address=None, extra=None, server_domain=None):
    try:
        return generate_protocol_link(uid, remark=remark, address=address, extra=extra, server_domain=server_domain)
    except Exception as e:
        logger.warning("Link generation failed for " + str(uid) + ": " + str(e))
        return ""


def generate_protocol_link(uid, remark="SulgX", address=None, extra=None, server_domain=None):
    protocol = (extra.get("protocol", "vless-ws") if extra else "vless-ws")
    if protocol in PROXY_PROTOCOLS:
        host = server_domain or get_domain()
        variant = (extra.get("mtproto_variant", "dd") or "dd") if extra else "dd"
        domain = (extra.get("mtproto_domain", "www.google.com") or "www.google.com") if extra else "www.google.com"
        port = int(extra.get("port") or 443) if extra else 443
        token = (extra.get("webproxy_token", "") or "") if extra else ""
        link = proxy_link_for_uid(uid, protocol, host, port, variant, domain, token)
        if link:
            return link
        return ""
    if protocol == "vmess-ws":
        return generate_vmess_link(uid, remark=remark, address=address, extra=extra, server_domain=server_domain)
    if protocol == "trojan-ws":
        return generate_trojan_link(uid, remark=remark, address=address, extra=extra, server_domain=server_domain)
    if protocol == "ss-ws":
        return generate_ss_link(uid, remark=remark, address=address, extra=extra, server_domain=server_domain)
    return generate_vless_link(uid, remark=remark, address=address, extra=extra, server_domain=server_domain)


