def _normalize_link_dict(link_dict):
    if not link_dict.get("uid"):
        return None
    for key, default in LINK_ROW_DEFAULTS.items():
        if key not in link_dict:
            link_dict[key] = default
        elif link_dict[key] is None and key not in ("expires_at", "proxy_line_id"):
            link_dict[key] = default
    if not link_dict.get("label"):
        link_dict["label"] = "Imported"
    if not link_dict.get("created_at"):
        link_dict["created_at"] = datetime.now(UTC).isoformat()
    if link_dict.get("protocol") not in VALID_PROTOCOLS:
        logger.warning("Link " + str(link_dict.get("uid")) + " has unknown protocol " + str(link_dict.get("protocol")) + ", treating as vless-ws")
        link_dict["protocol"] = "vless-ws"
    _norm_ss = normalize_ss_method(link_dict.get("ss_method"))
    link_dict["ss_method"] = _norm_ss if _norm_ss is not None else "2022-blake3-aes-256-gcm"
    if (link_dict.get("protocol") or "") in ("socks5", "http-proxy"):
        if not str(link_dict.get("proxy_username") or "").strip() or not str(link_dict.get("proxy_password") or "").strip():
            link_dict["proxy_username"] = str(link_dict.get("uid") or "")
            link_dict["proxy_password"] = str(link_dict.get("uid") or "")
    if link_dict.get("vmess_security") not in VMESS_SECURITY_METHODS:
        link_dict["vmess_security"] = "auto"
    link_dict["fingerprint"] = normalize_fingerprint(link_dict.get("fingerprint"))
    link_dict["custom_fp"] = normalize_fingerprint(link_dict.get("custom_fp"))
    if link_dict.get("profile") not in RESTRICTION_PROFILES:
        link_dict["profile"] = "custom" if link_dict.get("profile") in LEGACY_SERVICE_PROFILES else "default"
    if link_dict.get("ech_preset") not in ECH_PRESET_IDS and link_dict.get("ech_preset") != "custom":
        link_dict["ech_preset"] = ""
    if (link_dict.get("protocol") or "") in PROXY_PROTOCOLS:
        link_dict["last_test_ok"] = 0
        link_dict["last_test_ms"] = 0
        link_dict["last_test_detail"] = ""
        link_dict["last_test_at"] = ""
        link_dict["last_test_target"] = ""
        link_dict["last_test_verdict"] = ""
    return link_dict


