async def handle_telegram_users(chat_id):
    async with LINKS_LOCK:
        items = list(LINKS.values())
    lang = user_tg_langs.get(chat_id, default_tg_lang)
    if not items:
        msg = "No inbounds found." if lang == "en" else "هیچ اینباندی یافت نشد."
