async def create_proxied_connection(address, port, link):
    proxy_line = (link.get("outbound_proxy") or "").strip()
    if proxy_line:
        try:
            proxy_host, proxy_port, username, password = parse_outbound_proxy(proxy_line)
        except ValueError as e:
            raise ConnectionError("Configured outbound proxy is invalid: " + str(e))
        proxy_type = "socks5"
    else:
        proxy_line_id = link.get("proxy_line_id")
        if not proxy_line_id:
            return await asyncio.open_connection(address, port)
        proxy_row = await db_fetchone(
            "SELECT * FROM proxy_lines WHERE id = ?",
            "SELECT * FROM proxy_lines WHERE id = $1",
            (proxy_line_id,)
        )
        if not proxy_row or not proxy_row["is_active"]:
            if CONFIG.get("proxy_fallback_direct"):
                logger.warning(f"Proxy {proxy_line_id} not found or inactive, falling back to direct because proxy_fallback_direct is enabled")
                return await asyncio.open_connection(address, port)
            logger.warning(f"Proxy {proxy_line_id} not found or inactive, direct fallback is disabled")
            raise ConnectionError("Configured proxy is not found or inactive")
        proxy_type = proxy_row["type"].lower()
        proxy_host = proxy_row["host"]
        try:
            proxy_port = int(proxy_row["port"])
        except (ValueError, TypeError):
            raise ConnectionError("Configured proxy has an invalid port")
        username = proxy_row.get("username")
        password = decrypt_proxy_password(proxy_row.get("password"))
    if proxy_type not in ("socks4", "socks5", "http"):
        if CONFIG.get("proxy_fallback_direct"):
            logger.warning(f"Unsupported proxy type '{proxy_type}', falling back to direct because proxy_fallback_direct is enabled")
            return await asyncio.open_connection(address, port)
        logger.error(f"Unsupported proxy type '{proxy_type}'. Supported: socks4, socks5, http.")
        raise ConnectionError("Unsupported proxy type: " + proxy_type)
    try:
        auth_str = ""
        if username and password:
            safe_user = quote(username)
            safe_pass = quote(password)
            auth_str = f"{safe_user}:{safe_pass}@"
        proxy_url = f"{proxy_type}://{auth_str}{proxy_host}:{proxy_port}"
        proxy = Proxy.from_url(proxy_url)
        logger.info(f"Attempting proxied connection to {address}:{port} via {proxy_type}://{proxy_host}:{proxy_port}")
        sock = await asyncio.wait_for(
            proxy.connect(dest_host=address, dest_port=port),
            timeout=10.0
        )
        reader, writer = await asyncio.open_connection(sock=sock)
        tune_socket_for_link(writer, link)
        return reader, writer
    except asyncio.TimeoutError as e:
        logger.error(f"Proxy connection timed out for {proxy_host}:{proxy_port}.")
        if CONFIG.get("proxy_fallback_direct"):
            logger.warning("Falling back to direct connection because proxy_fallback_direct is enabled")
            return await asyncio.open_connection(address, port)
        raise ConnectionError("Proxy connection timed out") from e
    except ConnectionError:
        raise
    except Exception as e:
        logger.error(f"Proxy connection failed for {proxy_type}://{proxy_host}:{proxy_port} -> {address}:{port} : {e}")
        if CONFIG.get("proxy_fallback_direct"):
            logger.warning("Falling back to direct connection because proxy_fallback_direct is enabled")
            return await asyncio.open_connection(address, port)
        raise ConnectionError("Proxy connection failed: " + str(e)) from e


async def perform_proxy_test(proxy_row):
    proxy_id = proxy_row["id"]
    proxy_type = proxy_row["type"].lower()
    proxy_host = proxy_row["host"]
    proxy_port = int(proxy_row["port"])
    username = proxy_row.get("username")
    password = decrypt_proxy_password(proxy_row.get("password"))

    if proxy_type not in ("socks4", "socks5", "http"):
        await db_execute(
            "UPDATE proxy_lines SET last_test_status = 'unsupported', last_latency_ms = NULL WHERE id = ?",
            "UPDATE proxy_lines SET last_test_status = 'unsupported', last_latency_ms = NULL WHERE id = $1",
            (proxy_id,)
        )
        return {"id": proxy_id, "ok": False, "error": "Unsupported proxy type", "latency_ms": None, "status_code": None}

    test_targets = [
        ("httpbin.org", 80, b"GET /ip HTTP/1.0\r\nHost: httpbin.org\r\n\r\n", b'"origin"'),
        ("detectportal.firefox.com", 80, b"GET /success.txt HTTP/1.0\r\nHost: detectportal.firefox.com\r\n\r\n", b"success"),
    ]

    last_error = "No target succeeded"
    for host, port, request_bytes, expected_fragment in test_targets:
        try:
            start = time.time()
            auth_str = ""
            if username and password:
                safe_user = quote(username)
                safe_pass = quote(password)
                auth_str = f"{safe_user}:{safe_pass}@"
            proxy_url = f"{proxy_type}://{auth_str}{proxy_host}:{proxy_port}"
            proxy = Proxy.from_url(proxy_url)
            sock = await asyncio.wait_for(
                proxy.connect(dest_host=host, dest_port=port),
                timeout=8.0
            )
            reader, writer = await asyncio.open_connection(sock=sock)
            writer.write(request_bytes)
            await writer.drain()
            response = await asyncio.wait_for(reader.read(500), timeout=5.0)
            writer.close()
            await writer.wait_closed()
            latency = round((time.time() - start) * 1000)

            if expected_fragment in response:
                await db_execute(
                    "UPDATE proxy_lines SET last_test_status = 'ok', last_latency_ms = ? WHERE id = ?",
                    "UPDATE proxy_lines SET last_test_status = 'ok', last_latency_ms = $1 WHERE id = $2",
                    (latency, proxy_id)
                )
                return {"id": proxy_id, "ok": True, "latency_ms": latency, "status_code": 200}
            else:
                last_error = f"Unexpected response from {host}:{port}"
        except asyncio.TimeoutError:
            last_error = f"Timeout connecting to {host}:{port}"
        except Exception as e:
            last_error = f"Error connecting to {host}:{port}: {e}"

    await db_execute(
        "UPDATE proxy_lines SET last_test_status = 'error', last_latency_ms = NULL WHERE id = ?",
        "UPDATE proxy_lines SET last_test_status = 'error', last_latency_ms = NULL WHERE id = $1",
        (proxy_id,)
    )
    return {"id": proxy_id, "ok": False, "error": last_error, "latency_ms": None, "status_code": None}


@app.post("/api/proxy-lines/{pid}/test")
async def test_proxy_line(pid: int, request: Request, _=Depends(require_auth)):
    proxy_row = await db_fetchone(
        "SELECT * FROM proxy_lines WHERE id = ?",
        "SELECT * FROM proxy_lines WHERE id = $1",
        (pid,)
    )
    if not proxy_row:
        raise HTTPException(status_code=404, detail="Proxy not found")
    result = await perform_proxy_test(proxy_row)
    return result

_FORWARDER_HOP_BY_HOP = {"connection", "keep-alive", "proxy-authenticate", "proxy-authorization", "te", "trailer", "transfer-encoding", "upgrade", "content-length"}


def _forwarder_client_ip(request):
    ip = get_real_remote_address(request)
    try:
        parsed = ipaddress.ip_address(str(ip).strip())
    except ValueError:
        return "127.0.0.1"
    return str(parsed)


def _forwarder_headers(request, host, client_ip):
    headers = {}
    for key, value in request.headers.items():
        lower = key.lower()
        if lower in _FORWARDER_HOP_BY_HOP:
            continue
        if lower.startswith("x-forwarded-") or lower in ("forwarded",) or lower.startswith("cf-"):
            continue
        headers[key] = value
    headers["host"] = host
    headers["x-forwarded-for"] = client_ip
    headers["accept-encoding"] = "identity"
    return headers


async def _forward_http_to_telemt(request, uid, upstream_path, upstream_query=b"", body=b"", quota_uid=None):
    host = get_domain(request)
    client_ip = _forwarder_client_ip(request)
    port = _telemt_web_port_for_uid(uid)
    if not port:
        return JSONResponse(status_code=502, content={"ok": False, "detail": "telemt WEB child is not running for this inbound"})
    upstream = "http://127.0.0.1:" + str(port) + upstream_path
    if upstream_query:
        upstream += "?" + upstream_query.decode("latin-1")
    headers = _forwarder_headers(request, host, client_ip)
    timeout = httpx.Timeout(70.0, connect=10.0)
    try:
        client = httpx.AsyncClient(timeout=timeout, follow_redirects=False, trust_env=False)
        req = client.build_request(request.method, upstream, headers=headers, content=body)
        resp = await client.send(req, stream=True)
    except httpx.TimeoutException:
        return JSONResponse(status_code=504, content={"ok": False, "detail": "upstream WEB proxy timed out"})
    except Exception as exc:
        return JSONResponse(status_code=502, content={"ok": False, "detail": "upstream WEB proxy error: " + str(exc)})
    resp_headers = {k: v for k, v in resp.headers.items() if k.lower() not in _FORWARDER_HOP_BY_HOP}
    status = resp.status_code
    total = {"down": 0}

    async def _forward_gen():
        try:
            async for chunk in resp.aiter_raw():
                if chunk:
                    total["down"] += len(chunk)
                    yield chunk
        finally:
            try:
                await resp.aclose()
            except Exception:
                pass
            try:
                await client.aclose()
            except Exception:
                pass
            if total["down"]:
                try:
                    charged = await consume_quota_partial(quota_uid or uid, total["down"])
                    if charged and quota_uid and quota_uid != _TELEMT_ROOT_CHILD_UID:
                        _WEB_TOKEN_CHARGED[str(quota_uid)] = int(_WEB_TOKEN_CHARGED.get(str(quota_uid)) or 0) + int(charged)
                except Exception:
                    pass

    return StreamingResponse(_forward_gen(), status_code=status, headers=resp_headers)


async def _forward_ws_to_telemt(websocket, uid, upstream_path, quota_uid=None):
    host = get_domain(websocket)
    client_ip = _forwarder_client_ip(websocket)
    port = _telemt_web_port_for_uid(uid)
    if not port:
        await websocket.close(code=1011)
        return
    offered = websocket.headers.get("sec-websocket-protocol", "")
    subprotocols = [part.strip() for part in offered.split(",") if part.strip()] or None
    raw = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    raw.settimeout(10.0)
    try:
        raw.connect(("127.0.0.1", int(port)))
    except OSError as exc:
        logger.warning("WEB WS forwarder TCP connect to telemt failed on port " + str(port) + ": " + str(exc))
        try:
            raw.close()
        except OSError:
            pass
        await websocket.close(code=1011)
        return
    raw.settimeout(None)
    url = "ws://" + host + upstream_path
    try:
        ws_major = int(str(websockets.version.version).split(".")[0])
    except (AttributeError, TypeError, ValueError):
        ws_major = 12
    ws_header_key = "additional_headers" if ws_major >= 13 else "extra_headers"
    try:
        upstream_ws = await websockets.connect(url, sock=raw, subprotocols=subprotocols, open_timeout=10.0, ping_interval=None, max_size=None, compression=None, **{ws_header_key: {"X-Forwarded-For": client_ip}})
    except Exception as exc:
        logger.warning("WEB WS forwarder upstream WS connect failed for " + str(upstream_path) + ": " + str(exc))
        try:
            raw.close()
        except OSError:
            pass
        await websocket.close(code=1011)
        return
    await websocket.accept(subprotocol=upstream_ws.subprotocol)
    down_total = 0
    up_total = 0

    async def _client_to_upstream():
        nonlocal up_total
        try:
            while True:
                message = await websocket.receive()
                if message.get("type") == "websocket.disconnect":
                    break
                data = message.get("bytes")
                if data is None:
                    text = message.get("text")
                    data = text.encode("utf-8") if text else b""
                if data:
                    up_total += len(data)
                    await upstream_ws.send(data)
        except Exception:
            pass

    async def _upstream_to_client():
        nonlocal down_total
        try:
            while True:
                try:
                    data = await asyncio.wait_for(upstream_ws.recv(), timeout=15.0)
                except asyncio.TimeoutError:
                    try:
                        await upstream_ws.ping()
                    except Exception:
                        break
                    continue
                if isinstance(data, str):
                    data = data.encode("utf-8")
                down_total += len(data)
                await websocket.send_bytes(data)
        except Exception:
            pass

    pump_tasks = [asyncio.create_task(_client_to_upstream()), asyncio.create_task(_upstream_to_client())]
    _done, pending = await asyncio.wait(pump_tasks, return_when=asyncio.FIRST_COMPLETED)
    for task in pending:
        task.cancel()
    await asyncio.gather(*pending, return_exceptions=True)
    try:
        await upstream_ws.close()
    except Exception:
        pass
    try:
        await websocket.close()
    except Exception:
        pass
    try:
        if up_total:
            charged = await consume_quota_partial(quota_uid or uid, up_total)
            if charged and quota_uid and quota_uid != _TELEMT_ROOT_CHILD_UID:
                _WEB_TOKEN_CHARGED[str(quota_uid)] = int(_WEB_TOKEN_CHARGED.get(str(quota_uid)) or 0) + int(charged)
    except Exception:
        pass
    try:
        if down_total:
            charged = await consume_quota_partial(quota_uid or uid, down_total)
            if charged and quota_uid and quota_uid != _TELEMT_ROOT_CHILD_UID:
                _WEB_TOKEN_CHARGED[str(quota_uid)] = int(_WEB_TOKEN_CHARGED.get(str(quota_uid)) or 0) + int(charged)
    except Exception:
        pass


async def _web_alias_retire(old_token, current_token, uid):
    old_token = str(old_token or "").strip().lower()
    current_token = str(current_token or "").strip().lower()
    uid = str(uid or "")
    if not old_token or not current_token or not uid or old_token == current_token:
        return
    try:
        await db_execute("INSERT INTO webproxy_token_aliases (old_token, current_token, uid, retired_at) VALUES (?, ?, ?, ?) ON CONFLICT(old_token) DO UPDATE SET current_token = excluded.current_token, uid = excluded.uid, retired_at = excluded.retired_at", "INSERT INTO webproxy_token_aliases (old_token, current_token, uid, retired_at) VALUES ($1, $2, $3, $4) ON CONFLICT (old_token) DO UPDATE SET current_token = EXCLUDED.current_token, uid = EXCLUDED.uid, retired_at = EXCLUDED.retired_at", (old_token, current_token, uid, datetime.now(UTC).isoformat()))
    except Exception:
        pass
    _WEB_TOKEN_ALIASES[old_token] = (current_token, uid)


async def _web_alias_drop_for_token(token):
    token = str(token or "").strip().lower()
    if not token:
        return
    try:
        await db_execute("DELETE FROM webproxy_token_aliases WHERE old_token = ? OR current_token = ?", "DELETE FROM webproxy_token_aliases WHERE old_token = $1 OR current_token = $2", (token, token))
    except Exception:
        pass
    _WEB_TOKEN_ALIASES.pop(token, None)
    for _old in [k for k, v in list(_WEB_TOKEN_ALIASES.items()) if v[0] == token]:
        _WEB_TOKEN_ALIASES.pop(_old, None)


_TCP_PROXY_PROVIDER_NAME = ""
_TCP_PROXY_CONFIGURED = False
_TCP_PROXY_DEFAULT_MAX_CONN_PER_IP = 3


async def _tcp_proxy_settings():
    token = (os.environ.get("RAILWAY_TOKEN") or "").strip()
    service_id = (os.environ.get("RAILWAY_SERVICE_ID") or "").strip()
    environment_id = (os.environ.get("RAILWAY_ENVIRONMENT_ID") or "").strip()
    provider_name = (os.environ.get("TCP_PROXY_PROVIDER") or "").strip().lower()
    if not token:
        try:
            row = await db_fetchone("SELECT value FROM settings WHERE key = ?", "SELECT value FROM settings WHERE key = $1", ("railway_token",))
            if row and row.get("value"):
                token = decrypt_proxy_password(str(row["value"]))
        except Exception:
            token = ""
    if not service_id:
        try:
            row = await db_fetchone("SELECT value FROM settings WHERE key = ?", "SELECT value FROM settings WHERE key = $1", ("railway_service_id",))
            service_id = str((row or {}).get("value") or "").strip()
        except Exception:
            service_id = ""
    if not environment_id:
        try:
            row = await db_fetchone("SELECT value FROM settings WHERE key = ?", "SELECT value FROM settings WHERE key = $1", ("railway_environment_id",))
            environment_id = str((row or {}).get("value") or "").strip()
        except Exception:
            environment_id = ""
    if not provider_name:
        try:
            row = await db_fetchone("SELECT value FROM settings WHERE key = ?", "SELECT value FROM settings WHERE key = $1", ("tcp_proxy_provider",))
            provider_name = str((row or {}).get("value") or "").strip().lower()
        except Exception:
            provider_name = ""
    if not provider_name:
        provider_name = "railway" if token else "none"
    return {"token": token, "service_id": service_id, "environment_id": environment_id, "provider": provider_name}


async def _tcp_proxy_configure_provider():
    global _TCP_PROXY_PROVIDER_NAME, _TCP_PROXY_CONFIGURED
    _TCP_PROXY_CONFIGURED = False
    _TCP_PROXY_PROVIDER_NAME = "none"
    if tgproxy is None:
        return "none"
    settings = await _tcp_proxy_settings()
    name = settings.get("provider") or "none"
    provider = None
    if name == "mock":
        provider = tgproxy.MockTcpProxyProvider()
    elif name == "railway":
        provider = tgproxy.RailwayTcpProxyProvider(settings.get("token") or "", settings.get("service_id") or "", settings.get("environment_id") or "")
        if not provider.has_token():
            provider = None
    if provider is None:
        tgproxy.set_tcp_proxy_provider(None)
        return "none"
    tgproxy.set_tcp_proxy_provider(provider)
    _TCP_PROXY_PROVIDER_NAME = provider.name
    _TCP_PROXY_CONFIGURED = True
    return provider.name


def _tcp_proxy_attach(link, row):
    if link is None or row is None:
        return
    link["tcp_provider"] = str(row.get("provider") or "")
    link["tcp_proxy_id"] = str(row.get("proxy_id") or "")
    link["tcp_public_domain"] = str(row.get("public_domain") or "")
    link["tcp_public_port"] = int(row.get("public_port") or 0)
    link["tcp_local_port"] = int(row.get("local_port") or 0)
    link["tcp_max_conn_per_ip"] = int(row.get("max_conn_per_ip") or 0)
    link["tcp_created_at"] = str(row.get("created_at") or "")


def _tcp_proxy_detach(link):
    if link is None:
        return
    for key in ("tcp_provider", "tcp_proxy_id", "tcp_public_domain", "tcp_public_port", "tcp_local_port", "tcp_max_conn_per_ip", "tcp_created_at"):
        link.pop(key, None)


async def _tcp_proxy_row(uid):
    try:
        rows = await db_fetchall("SELECT * FROM tcp_proxies WHERE uid = ?", "SELECT * FROM tcp_proxies WHERE uid = $1", (uid,))
    except Exception:
        return None
    if not rows:
        return None
    return dict(rows[0])


async def _tcp_proxy_provision(link):
    if link is None:
        return None
    if (link.get("protocol") or "") not in ("socks5", "mtproto", "http-proxy"):
        return None
    if not link.get("active"):
        return None
    uid = str(link.get("uid") or "")
    if not uid:
        return None
    existing = await _tcp_proxy_row(uid)
    if existing:
        _tcp_proxy_attach(link, existing)
        return existing
    if tgproxy is None:
        return None
    provider = tgproxy.tcp_proxy_provider()
    if provider is None or not provider.has_token():
        return None
    try:
        local_port = int(link.get("port") or 0)
    except (TypeError, ValueError):
        local_port = 0
    if not local_port:
        return None
    try:
        created = await provider.create_public_proxy(local_port)
    except Exception as exc:
        logger.warning("TCP proxy provisioning failed for inbound " + uid + ": " + str(exc))
        link["tcp_provision_error"] = str(exc)
        return None
    now = datetime.now(UTC).isoformat()
    try:
        await db_execute("INSERT OR REPLACE INTO tcp_proxies (uid, provider, proxy_id, public_domain, public_port, local_port, max_conn_per_ip, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", "INSERT INTO tcp_proxies (uid, provider, proxy_id, public_domain, public_port, local_port, max_conn_per_ip, created_at) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) ON CONFLICT (uid) DO UPDATE SET provider = $2, proxy_id = $3, public_domain = $4, public_port = $5, local_port = $6, max_conn_per_ip = $7, created_at = $8", (uid, provider.name, str(created.get("id") or ""), str(created.get("domain") or ""), int(created.get("port") or 0), int(created.get("application_port") or local_port), _TCP_PROXY_DEFAULT_MAX_CONN_PER_IP, now))
    except Exception as exc:
        logger.warning("TCP proxy record save failed for inbound " + uid + ": " + str(exc))
        try:
            await provider.delete_public_proxy(str(created.get("id") or ""))
        except Exception:
            pass
        return None
    row = {"uid": uid, "provider": provider.name, "proxy_id": str(created.get("id") or ""), "public_domain": str(created.get("domain") or ""), "public_port": int(created.get("port") or 0), "local_port": int(created.get("application_port") or local_port), "max_conn_per_ip": _TCP_PROXY_DEFAULT_MAX_CONN_PER_IP, "created_at": now}
    _tcp_proxy_attach(link, row)
    link.pop("tcp_provision_error", None)
    link.pop("tcp_auto_released", None)
    logger.info("TCP proxy provisioned for inbound " + uid + ": " + str(created.get("domain") or "") + ":" + str(created.get("port") or 0))
    return row


async def _tcp_proxy_release(uid, reason=""):
    uid = str(uid or "")
    if not uid:
        return False
    row = await _tcp_proxy_row(uid)
    link = LINKS.get(uid)
    if row is None:
        if link is not None:
            _tcp_proxy_detach(link)
        return False
    if tgproxy is None:
        logger.warning("TCP proxy release skipped for inbound " + uid + ", telegram module is not loaded, record kept for reconciliation")
        return False
    provider = tgproxy.tcp_proxy_provider()
    if provider is None:
        logger.warning("TCP proxy release skipped for inbound " + uid + ", no provider is configured, record kept for reconciliation")
        return False
    removed = False
    try:
        removed = await provider.delete_public_proxy(str(row.get("proxy_id") or ""))
    except Exception as exc:
        logger.warning("TCP proxy delete failed for inbound " + uid + ": " + str(exc))
        removed = False
    if removed:
        try:
            await db_execute("DELETE FROM tcp_proxies WHERE uid = ?", "DELETE FROM tcp_proxies WHERE uid = $1", (uid,))
        except Exception as exc:
            logger.warning("TCP proxy record delete failed for inbound " + uid + ": " + str(exc))
            removed = False
    if link is not None:
        _tcp_proxy_detach(link)
        if reason:
            link["tcp_auto_released"] = reason
    if removed:
        logger.info("TCP proxy released for inbound " + uid + (": " + reason if reason else ""))
    else:
        logger.warning("TCP proxy release incomplete for inbound " + uid + ", record kept for reconciliation")
    return removed


async def _tcp_proxy_reconcile():
    try:
        rows = await db_fetchall("SELECT * FROM tcp_proxies", "SELECT * FROM tcp_proxies")
    except Exception:
        return {"released": 0, "kept": 0}
    released = 0
    kept = 0
    _provider = tgproxy.tcp_proxy_provider() if tgproxy is not None else None
    _live_ids = None
    if _provider is not None:
        try:
            _live_ids = {str(_p.get("id") or "") for _p in await _provider.list_public_proxies()}
        except Exception as exc:
            logger.warning("TCP proxy reconcile could not list remote proxies: " + str(exc))
            _live_ids = None
    for row in rows or []:
        uid = str((row or {}).get("uid") or "")
        if not uid:
            continue
        link = LINKS.get(uid)
        if link is not None:
            _tcp_proxy_attach(link, dict(row))
            kept += 1
            if _live_ids is not None and str((row or {}).get("proxy_id") or "") not in _live_ids:
                _tcp_proxy_detach(link)
                try:
                    await db_execute("DELETE FROM tcp_proxies WHERE uid = ?", "DELETE FROM tcp_proxies WHERE uid = $1", (uid,))
                except Exception:
                    pass
                _recreated = await _tcp_proxy_provision(link)
                if _recreated is not None:
                    logger.info("TCP proxy re-created on boot for inbound " + uid + ": remote proxy was gone")
                else:
                    logger.warning("TCP proxy re-create failed on boot for inbound " + uid + ", inbound left without a public proxy")
            continue
        if await _tcp_proxy_release(uid, "orphaned proxy for a deleted inbound"):
            released += 1
        else:
            kept += 1
    return {"released": released, "kept": kept}


def _tcp_proxy_status(link):
    if link is None or not link.get("tcp_public_domain"):
        return None
    used = int(link.get("used_bytes") or 0)
    limit = int(link.get("limit_bytes") or 0)
    remaining_hours = None
    expires = parse_expires_at(link.get("expires_at"))
    if expires is not None:
        remaining_hours = round(max(0.0, (expires - datetime.now(UTC)).total_seconds()) / 3600.0, 1)
    return {"provider": str(link.get("tcp_provider") or ""), "domain": str(link.get("tcp_public_domain") or ""), "port": int(link.get("tcp_public_port") or 0), "proxy_id": str(link.get("tcp_proxy_id") or ""), "bytes_used": used, "traffic_limit_bytes": limit, "traffic_percent": round(used / limit * 100, 1) if limit > 0 else None, "expires_remaining_hours": remaining_hours, "max_conn_per_ip": int(link.get("tcp_max_conn_per_ip") or 0), "auto_released": str(link.get("tcp_auto_released") or "")}


def _tcp_proxy_missing_text():
    return "No TCP proxy provider is configured, so this inbound has no published raw TCP port. Configure a Railway token (RAILWAY_TOKEN plus service and environment id) or use a VPS with open ports. " + "هیچ ارائه‌دهنده TCP Proxy پیکربندی نشده است، پس این اینباند پورت TCP خام منتشرشده ندارد. توکن Railway را تنظیم کنید یا از VPS با پورت‌های باز استفاده کنید."


def _web_link_for_token(token):
    token = str(token or "").strip().lower()
    if not _webproxy_valid_token(token):
        return None
    for row in LINKS.values():
        if (row.get("protocol") or "") == "webproxy" and str(row.get("webproxy_token") or "").strip().lower() == token and row.get("active"):
            return row
    aliased = _WEB_TOKEN_ALIASES.get(token)
    if aliased:
        current_token, _alias_uid = aliased
        for row in LINKS.values():
            if (row.get("protocol") or "") == "webproxy" and str(row.get("webproxy_token") or "").strip().lower() == current_token and row.get("active"):
                logger.info("WEB bridge request used retired token alias " + token + " for inbound " + str(row.get("uid", "")))
                return row
    return None


async def _root_bridge_response(request):
    capability = request.query_params.get("bridge", "") or request.query_params.get("capability", "") or request.query_params.get("cap", "") or request.headers.get("x-tgweb-capability", "")
    if not capability:
        return None
    host = get_domain(request)
    matched = None
    for candidate in sorted([l for l in LINKS.values() if (l.get("protocol") or "") == "webproxy" and l.get("active")], key=lambda l: str(l.get("created_at") or "")):
        token = str(candidate.get("webproxy_token") or "").strip().lower()
        try:
            expected_v1 = _web_capability_v1(host, token, candidate)
        except ValueError:
            continue
        if hmac_mod.compare_digest(capability, expected_v1):
            matched = candidate
            break
    if matched is None:
        return Response(content="no active WEB proxy inbound for this bridge capability", status_code=404, media_type="text/plain", headers={"Cache-Control": "no-store"})
    query = request.url.query.encode("latin-1") if request.url.query else b""
    return await _forward_http_to_telemt(request, _TELEMT_ROOT_CHILD_UID, "/", query, body=b"", quota_uid=str(matched.get("uid", "")))


@app.api_route("/", methods=["GET", "HEAD"])
async def root(request: Request):
    bridge = await _root_bridge_response(request)
    if bridge is not None:
        return bridge
    if CAMOUFLAGE_URL:
        try:
            async with httpx.AsyncClient(timeout=10.0, follow_redirects=True) as client:
                headers = {
                    "User-Agent": request.headers.get("user-agent", "Mozilla/5.0"),
                    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                    "Accept-Language": "en-US,en;q=0.5",
                }
                resp = await client.get(CAMOUFLAGE_URL, headers=headers)
                return Response(content=resp.text, media_type=resp.headers.get("content-type", "text/html"))
        except Exception:
            pass
    if LANDING_REDIRECT:
        return RedirectResponse(LANDING_REDIRECT, status_code=302)
    return HTMLResponse(content=LANDING_HTML)

