async def _read_loadavg_cpu():
    def _read():
        with open("/proc/loadavg", "r") as f:
            return float(f.readline().split()[0]) * 10
    try:
        return await asyncio.to_thread(_read)
    except (OSError, ValueError, IndexError):
        return None




def _disk_path_for_db():
    raw = str(CONFIG.get("db_path", "") or "").strip()
    if not raw or DB_BACKEND == "postgresql":
        return "/"
    path = os.path.dirname(os.path.abspath(raw))
    while path and not os.path.isdir(path):
        parent = os.path.dirname(path)
        if parent == path:
            return "/"
        path = parent
    return path or "/"


async def _read_disk_usage():
    path = _disk_path_for_db()
    try:
        usage = await asyncio.to_thread(shutil.disk_usage, path)
    except (OSError, ValueError):
        return None, None, None, path
    total = float(usage.total) / (1024 ** 3)
    free = float(usage.free) / (1024 ** 3)
    if total <= 0:
        return None, None, None, path
    return round(free, 1), round(total, 1), round(100.0 * (total - free) / total, 1), path

@app.get("/stats")
async def get_stats(_=Depends(require_auth)):
    global TIMEZONE_OFFSET
    async with connections_lock:
        conn_count = len(connections)
    cpu = 0.0
    try:
        cpu = await asyncio.to_thread(psutil.cpu_percent, 0.1)
    except Exception:
        cpu = None
    if cpu == 0.0 or cpu is None:
        cpu = await _read_loadavg_cpu()
    mem_percent = 0
    try:
        mem_percent = psutil.virtual_memory().percent
    except Exception:
        pass
    disk_free, disk_total, disk_percent, disk_path = await _read_disk_usage()
    now = datetime.now(UTC) + timedelta(hours=TIMEZONE_OFFSET)
    today_str = now.strftime("%Y-%m-%d")
    rows = await db_fetchall(
        "SELECT hour, bytes FROM hourly_traffic WHERE hour LIKE ? ORDER BY hour ASC",
        "SELECT hour, bytes FROM hourly_traffic WHERE hour LIKE $1 ORDER BY hour ASC",
        (today_str + '%',)
    )
    hourly_dict = {f"{h:02d}:00": 0 for h in range(24)}
    for r in rows:
        hour_part = r["hour"][-5:] if len(r["hour"]) >= 5 else r["hour"]
        if hour_part in hourly_dict:
            hourly_dict[hour_part] = r["bytes"]
    async with traffic_buffer_lock:
        for h_key, b_val in traffic_buffer["hourly"].items():
            hour_part = h_key[-5:] if len(h_key) >= 5 else h_key
            if hour_part in hourly_dict:
                hourly_dict[hour_part] += b_val
    sorted_hours = [f"{h:02d}:00" for h in range(24)]
    hourly_data = {h: hourly_dict[h] for h in sorted_hours}
    month_start = now.strftime("%Y-%m") + "-01"
    monthly_bytes = 0
    month_rows = await db_fetchall(
        "SELECT SUM(bytes) as total FROM daily_traffic WHERE day >= ?",
        "SELECT SUM(bytes) as total FROM daily_traffic WHERE day >= $1",
        (month_start,)
    )
    if month_rows and month_rows[0]["total"]:
        monthly_bytes = month_rows[0]["total"]
    monthly_limit = 0
    limit_row = await db_fetchone("SELECT value FROM settings WHERE key='monthly_limit_gb'", "SELECT value FROM settings WHERE key='monthly_limit_gb'")
    if limit_row and limit_row["value"]:
        try:
            monthly_limit = float(limit_row["value"]) * 1024**3
        except (ValueError, TypeError):
            pass
    return {
        "active_connections": conn_count,
        "total_traffic_mb": round(stats["total_bytes"]/(1024*1024), 2),
        "total_requests": stats["total_requests"],
        "total_errors": stats["total_errors"],
        "uptime": uptime(),
        "timestamp": datetime.now(UTC).isoformat(),
        "recent_errors": list(error_logs)[-20:],
        "links_count": len(LINKS),
        "protocol_counts": {p: sum(1 for l in LINKS.values() if (l.get("protocol") or "vless-ws") == p) for p in VALID_PROTOCOLS},
        "domain": get_domain(),
        "cpu_percent": cpu,
        "memory_percent": mem_percent,
        "disk_percent": disk_percent,
        "disk_free_gb": disk_free,
        "disk_total_gb": disk_total,
        "disk_path": disk_path,
        "hourly_traffic": hourly_data,
        "hourly_labels": sorted_hours,
        "upload_bytes": stats["upload_bytes"],
        "download_bytes": stats["download_bytes"],
        "monthly_usage_bytes": monthly_bytes,
        "monthly_limit_bytes": int(monthly_limit),
        "links_total_used_bytes": sum(int(l.get("used_bytes") or 0) + _live_proxy_unflushed_bytes(str(l.get("uid") or "")) for l in LINKS.values()),
        "db_fresh_at_boot": DB_FRESH_AT_BOOT,
        "db_path": DB_PATH_AT_BOOT,
        "db_backend": DB_BACKEND,
    }

@app.get("/stats/detailed")
async def get_detailed_stats(_=Depends(require_auth)):
    async with LINKS_LOCK:
        links = list(LINKS.values())
    active = sum(1 for l in links if l["active"])
    inactive = sum(1 for l in links if not l["active"])
    expired = 0
    now = datetime.now(UTC)
    for l in links:
        if l.get("expires_at"):
            exp = parse_expires_at(l["expires_at"])
            if exp and exp < now:
                expired += 1
    _local_now = datetime.now(UTC) + timedelta(hours=TIMEZONE_OFFSET)
    today = _local_now.strftime("%Y-%m-%d")
    today_row = await db_fetchone("SELECT SUM(bytes) as total FROM daily_traffic WHERE day = ?", "SELECT SUM(bytes) as total FROM daily_traffic WHERE day = $1", (today,))
    today_bytes = today_row["total"] if today_row and today_row["total"] else 0
    daily_rows = await db_fetchall("SELECT day, SUM(bytes) as total FROM daily_traffic GROUP BY day ORDER BY day DESC LIMIT 7",
                                   "SELECT day, SUM(bytes) as total FROM daily_traffic GROUP BY day ORDER BY day DESC LIMIT 7")
    daily_traffic = {row["day"]: row["total"] for row in daily_rows}
    return {
        "total_links": len(links),
        "active_links": active,
        "inactive_links": inactive,
        "expired_links": expired,
        "today_traffic_bytes": today_bytes,
        "daily_traffic": daily_traffic,
    }

@app.get("/api/login-logs")
async def get_login_logs(_=Depends(require_auth)):
    rows = await db_fetchall(
        "SELECT id, timestamp, ip, success, user_agent, path, browser, os, country, city, isp, org FROM login_logs ORDER BY timestamp DESC LIMIT 20",
        "SELECT id, timestamp, ip, success, user_agent, path, browser, os, country, city, isp, org FROM login_logs ORDER BY timestamp DESC LIMIT 20"
    )
    result = [dict(r) for r in rows]
    now = time.monotonic()
    backfilled = 0
    for row in result:
        if backfilled >= 5:
            break
        if (row.get("country") or "").strip():
            continue
        ip = str(row.get("ip") or "").strip()
        try:
            parsed = ipaddress.ip_address(ip)
        except ValueError:
            continue
        if not parsed.is_global:
            continue
        if now - GEO_BACKFILL_ATTEMPTED.get(ip, 0.0) < 300:
            continue
        GEO_BACKFILL_ATTEMPTED[ip] = now
        spawn_background(update_login_location(int(row["id"]), ip))
        backfilled += 1
    return {"logs": result, "geo_status": dict(GEO_STATUS)}

