from starlette.convertors import Convertor, register_url_convertor


class _Hex12Convertor(Convertor):
    regex = "[0-9a-f]{12}"

    def convert(self, value):
        return str(value).lower()

    def to_string(self, value):
        return str(value).lower()


register_url_convertor("hex12", _Hex12Convertor())


@app.api_route("/{token:hex12}/{rest:path}", methods=["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"])
async def webproxy_forwarder(request: Request, token: str, rest: str):
    token = str(token or "").strip().lower()
    link = _web_link_for_token(token)
    if link is None:
        _warn_ip = ""
        try:
            _warn_ip = str((request.client.host if request.client else "") or "")
        except Exception:
            _warn_ip = ""
        logger.warning("WEB bridge request for unknown token path token=" + str(token) + " path=" + str(request.url.path) + " ip=" + _warn_ip)
        raise HTTPException(status_code=404, detail="Not found")
    uid = str(link.get("uid", ""))
    body = await request.body()
    if body:
        try:
            await consume_quota_partial(uid, len(body))
        except Exception:
            pass
    query = request.url.query.encode("latin-1") if request.url.query else b""
    bridge_v1 = _web_verify_token_bridge(request, token, link)
    if bridge_v1 is False:
        return Response(content="no active WEB proxy inbound for this bridge capability", status_code=404, media_type="text/plain", headers={"Cache-Control": "no-store"})
    if bridge_v1:
        query = _web_rewrite_bridge_query(query, bridge_v1)
    return await _forward_http_to_telemt(request, _TELEMT_ROOT_CHILD_UID, "/" + rest, query, body=body, quota_uid=uid)


@app.api_route("/{full_path:path}", methods=["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"])
async def dynamic_xhttp_router(full_path: str, request: Request):
    """
    Catch‑all router for XHTTP traffic.
    Handles three path formats:
      - stream-one:        POST <base_path>                         (exact base path)
      - stream-up/packet-up:
           <base_path>/<mode>/<user_uuid>/<session_id>[/<seq>]
      - legacy (no mode):  <base_path>/<session_id>[/<seq>]         (kept for compatibility)
    """
    base_paths = set()
    if full_path.startswith("api/v1/"):
        _bare_body = await request.body()
        if _bare_body:
            try:
                await consume_quota_partial(_TELEMT_ROOT_CHILD_UID, len(_bare_body))
            except Exception:
                pass
        _bare_query = request.url.query.encode("latin-1") if request.url.query else b""
        return await _forward_http_to_telemt(request, _TELEMT_ROOT_CHILD_UID, "/" + full_path, _bare_query, body=_bare_body)
    if request.method in ("GET", "HEAD") and re.fullmatch(r"[0-9a-f]{12}", full_path or ""):
        _bare_token = full_path.strip().lower()
        _bare_link = _web_link_for_token(_bare_token)
        if _bare_link is not None:
            _bare_body = await request.body()
            if _bare_body:
                try:
                    await consume_quota_partial(str(_bare_link.get("uid", "")), len(_bare_body))
                except Exception:
                    pass
            _bare_query = request.url.query.encode("latin-1") if request.url.query else b""
            _bare_bridge_v1 = _web_verify_token_bridge(request, _bare_token, _bare_link)
            if _bare_bridge_v1 is False:
                return Response(content="no active WEB proxy inbound for this bridge capability", status_code=404, media_type="text/plain", headers={"Cache-Control": "no-store"})
            if _bare_bridge_v1:
                _bare_query = _web_rewrite_bridge_query(_bare_query, _bare_bridge_v1)
            return await _forward_http_to_telemt(request, _TELEMT_ROOT_CHILD_UID, "/", _bare_query, body=_bare_body, quota_uid=str(_bare_link.get("uid", "")))
        if request.query_params.get("bridge", "") or request.query_params.get("capability", "") or request.query_params.get("cap", "") or request.query_params.get("secret", "") or request.query_params.get("token", ""):
            return Response(content="no active WEB proxy inbound for this token", status_code=404, media_type="text/plain", headers={"Cache-Control": "no-store"})
    async with LINKS_LOCK:
        for uid, link in LINKS.items():
            if not link.get("active"):
                continue
            proto = link.get("protocol", "vless-ws")
            if proto.startswith("xhttp-"):
                bp = link.get("custom_path") or DEFAULT_XHTTP_PATH
                bp = bp.strip("/")
                if bp:
                    base_paths.add(bp)

    default_bp = DEFAULT_XHTTP_PATH.strip("/")
    if default_bp:
        base_paths.add(default_bp)

    for bp in base_paths:
        if full_path.strip("/") == bp:
            if request.method == "POST":
                return await xhttp_stream_one(bp, request)
            raise HTTPException(status_code=405, detail="Method Not Allowed")

    matched_base = None
    for bp in sorted(base_paths, key=lambda x: -len(x)):
        if full_path.startswith(bp + "/"):
            matched_base = bp
            break

    if not matched_base:
        raise HTTPException(status_code=404)

    remaining = full_path[len(matched_base):].strip("/")
    parts = remaining.split("/")

    VALID_MODES = {"stream-up", "packet-up", "stream-down"}
    if parts and parts[0] in VALID_MODES:
        if len(parts) >= 3:
            parts = parts[2:]
        elif len(parts) == 2:
            parts = []
        else:
            parts = parts[1:]

    if len(parts) == 1:
        session_id = parts[0]
        if request.method == "GET":
            return await xhttp_downlink(session_id, request)
        elif request.method == "POST":
            return await xhttp_stream_up(session_id, request)
        else:
            raise HTTPException(status_code=405, detail="Method Not Allowed")
    elif len(parts) == 2:
        session_id = parts[0]
        try:
            seq = int(parts[1])
        except ValueError:
            raise HTTPException(status_code=404)
        if request.method == "POST":
            return await xhttp_packet_up(session_id, seq, request)
        else:
            raise HTTPException(status_code=405, detail="Method Not Allowed")
    else:
        raise HTTPException(status_code=404)


if __name__ == "__main__":
    port = int(os.environ.get("PORT", CONFIG.get("port", 8000)))
    logger.info(f"Starting SulgX Panel on port {port}")
    uvicorn.run(
        app,
        host=os.environ.get("PANEL_BIND_HOST", "0.0.0.0"),
        port=port,
        workers=1,
        ws_per_message_deflate=False,
        proxy_headers=True,
        forwarded_allow_ips=list(TRUSTED_PROXY_IPS),
        log_level="info",
    )
